#include <iostream>

using namespace std;

class Person {
public:
    int age; // Age of the person
    int* score; // Pointer to store score

    // Constructor to initialize age and allocate memory for score
    Person(int age, int initialScore) {
        this->age = age;
        this->score = new int(initialScore);
    }

    // Copy constructor to create a deep copy of the Person object
    Person(const Person& other) {
        age = other.age;
        score = new int(*other.score);
    }

    // Display the details of the person
    void displayDetails() const {
        cout << "Age: " << age << endl;
        cout << "Score: " << *score << endl;
    }
};

int main() {
    Person personA(20, 2003);
    personA.displayDetails();

    // Create a copy of personA, invoking the copy constructor
    Person personB = personA; 
    *personA.score = 1000; // Modify score of personA

    cout << endl;

    // Display addresses of score pointers for both objects
    cout << "Address of score pointers: " << personA.score << " " << personB.score << endl; 

    personB.displayDetails();
    cout << endl;
    personA.displayDetails(); // Changes only affect personA's score

    return 0;
}

