#include <ros/ros.h>
#include "aseta_task_management/PhotoWaypointAction.h"

namespace aseta
{
	class DummyDrone
	{
	public:
		DummyDrone();
		~DummyDrone();

	private:
		void executeTask(const aseta_task_management::PhotoWaypointGoalConstPtr &goal);
		void updateDronePosition(const ros::TimerEvent& event);
		void publishFlightPath();
		void markTaskAsCompleted();

		ros::NodeHandle private_node_handle;
		actionlib::SimpleActionServer<aseta_task_management::PhotoWaypointAction> action_server;
		std::string reference_frame;
		geometry_msgs::Pose current_pose;
		geometry_msgs::Pose target_pose;
		std::vector<geometry_msgs::Pose> flight_path;

		ros::Timer position_update_timer;
		double update_rate;

		ros::Publisher path_publisher;
		double speed;

		boost::mutex mutex_lock;
		bool is_drone_moving;
	};

	DummyDrone::DummyDrone() :
		private_node_handle("~"),
		action_server(private_node_handle, "task_server", boost::bind(&DummyDrone::executeTask, this, _1), false),
		update_rate(0.1)
	{
		private_node_handle.param<double>("speed", speed, 1.0);
		ROS_INFO_STREAM("Vehicle speed is set to " << speed);

		private_node_handle.param<std::string>("reference_frame", reference_frame, "map");
		ROS_INFO_STREAM("Reference frame is set to " << reference_frame);

		path_publisher = private_node_handle.advertise<nav_msgs::Path>("sim", 1);
		position_update_timer = private_node_handle.createTimer(ros::Duration(update_rate), &DummyDrone::updateDronePosition, this);

		action_server.start();
	}

	DummyDrone::~DummyDrone() {}

	void DummyDrone::executeTask(const aseta_task_management::PhotoWaypointGoalConstPtr &goal)
	{
		ROS_INFO("Setting new task.");

		target_pose = goal->pose;
		mutex_lock.lock();
		is_drone_moving = true;
		mutex_lock.unlock();

		ros::Rate wait_rate(1.0);
		while (is_drone_moving)
		{
			if (action_server.isPreemptRequested() || !ros::ok())
			{
				ROS_INFO("Task preempted.");
				action_server.setPreempted();
				mutex_lock.lock();
				is_drone_moving = false;
				mutex_lock.unlock();
			}
			wait_rate.sleep();
		}

		if (!is_drone_moving)
		{
			aseta_task_management::PhotoWaypointResult result;
			ros::Time current_time = ros::Time::now();
			result.pose_stamped.pose = target_pose;
			result.pose_stamped.header.stamp = current_time;
			result.image.height = 1;
			result.image.width = 1;
			result.image.encoding = "rgb";
			result.image.data.push_back(100);
			result.image.header.stamp = current_time;
			ROS_INFO("Image taken.");
			action_server.setSucceeded(result);
		}
	}

	void DummyDrone::updateDronePosition(const ros::TimerEvent& event)
	{
		boost::lock_guard<boost::mutex> guard(mutex_lock);
		if (is_drone_moving)
		{
			double x_difference = target_pose.position.x - current_pose.position.x;
			double y_difference = target_pose.position.y - current_pose.position.y;
			double z_difference = target_pose.position.z - current_pose.position.z;
			double distance_to_target = sqrt(x_difference * x_difference + y_difference * y_difference + z_difference * z_difference);
			double movement_ratio = speed * update_rate / distance_to_target;

			if (movement_ratio >= 1.0)
			{
				current_pose.position = target_pose.position;
				is_drone_moving = false;
			}
			else
			{
				current_pose.position.x += movement_ratio * x_difference;
				current_pose.position.y += movement_ratio * y_difference;
				current_pose.position.z += movement_ratio * z_difference;
			}
			flight_path.push_back(current_pose);
		}

		publishFlightPath();
	}

	void DummyDrone::publishFlightPath()
	{
		if (ros::ok())
		{
			nav_msgs::Path path;
			path.header.frame_id = reference_frame;
			path.header.stamp = ros::Time();

			unsigned int sequence_number = 0;
			for (const auto& pose : flight_path)
			{
				geometry_msgs::PoseStamped pose_stamped;
				pose_stamped.pose = pose;
				pose_stamped.header.frame_id = reference_frame;
				pose_stamped.header.stamp = ros::Time();
				pose_stamped.header.seq = sequence_number++;
				path.poses.push_back(pose_stamped);
			}

			path_publisher.publish(path);
		}
	}

	void DummyDrone::markTaskAsCompleted() {}
}

int main(int argc, char *argv[])
{
	ros::init(argc, argv, "dummy_drone");
	aseta::DummyDrone drone_instance;
	ros::spin();
	return 0;
}

