    name = new char[40]; // Allocate memory for the name
    strcpy(name, n); // Copy the provided name into the allocated memory
    roll = rollNumber; // Set the roll number
}

// Method to display the student's name and roll number
void Student::display() const {
    cout << name << " " << roll; // Output the student's details
}

