    Student s1("xyz", 10); // Student with specified name and roll number
    s = s1; // Assign s1 to s
    s1.display(); // Display s1's details
    s.display(); // Display s's details
}

#include <iostream>

using namespace std;

class Human {
public:
    static int totalCount; // Static variable to track the total number of Human instances
    int instanceCount = 0; // Instance-specific count

    // Constructor increments the static count and instance count
    Human() {
        totalCount++;
        instanceCount++;
        cout << "Number of static humans: " << totalCount << endl;
    }

    // Destructor decrements the static count and reports remaining instances
    ~Human() {
        cout << endl;
        cout << "There are now " << totalCount << " humans remaining" << endl;
        totalCount--;
    }

    // Static method to display the total number of Human instances
    static void displayTotalHumans() {
        cout << "There are " << totalCount << " people" << endl;
    }
};

// Definition of the static variable outside the class
int Human::totalCount = 0;

int main() {
    // Creating multiple Human objects, sharing the static variable across instances
    Human anish;
    Human mrinal;
    Human lucky;
    Human vaibhav;

    // Display the total number of Human instances created
    Human::displayTotalHumans(); 
    cout << Human::totalCount; 

    return 0;    
}

#include <iostream>
#include <cstdio>

using namespace std;

int globalCounter = 1;

class PointerHandler {
public:
    int displayCounter();
};

inline int PointerHandler::displayCounter() {
    // Increment and display the global counter for a fixed number of iterations
    for (int iteration = 0; iteration < 5; iteration++, globalCounter++) {
        cout << globalCounter << " " << endl;
    }

    // Reset the counter if it reaches a specific value
    if (globalCounter == 26) {
        globalCounter = 1;
    }

    printf("\n");
}

int main() {
    PointerHandler objects[3]; // Array of PointerHandler objects

    // Display counter values using the object array
    for (int index = 0; index < 5; index++) {
        objects[index].displayCounter();
    }

    PointerHandler* pointerToObjects = objects; // Assigning the address of the first object to a pointer

    printf("Pointer to object: \n");

    // Display counter values using the pointer to the object array
    for (int index = 0; index < 5; index++) {
        (pointerToObjects + index)->displayCounter();
    }

    return 0;
}

