// Represents a single row retrieved from the database.
struct DatabaseRow {
    DatabaseRow() {}

    DatabaseRow(unsigned int fieldCount, MYSQL_ROW data) : numFields(fieldCount), rowData(data) {}

    unsigned int numFields;
    MYSQL_ROW rowData;
};

// Manages database connections and operations.
class Database {
public:
    // Initializes a new database connection with the provided credentials.
    Database(const char *host, const char *user, const char *password, const char *databaseName);

    // Cleans up the database connection.
    ~Database();

    // Executes a SELECT query and returns the number of rows retrieved.
    unsigned int select(std::string &query);

    // Executes a SELECT query and returns the number of rows retrieved.
    unsigned int select(const char *query);

    // Executes an UPDATE query and returns the number of affected rows.
    long update(const char *query);

    // Executes an UPDATE query and returns the number of affected rows.
    long update(std::string &query);

    // Retrieves the most recent row from the last executed query.
    DatabaseRow getRow();

    // Retrieves all rows from the last executed query.
    std::vector<DatabaseRow> getResults();

    // Releases the resources associated with the last executed query.
    bool release();

    // Escapes a variable to prevent SQL injection.
    void escape(std::string &variable) const;

    // Sets a variable to a default value if it is null, or adds single quotes.
    void setDefaultValue(std::string &variable) const;

    // Checks if a variable can be interpreted as an integer.
    bool isInteger(std::string &variable) const;

private:
    MYSQL mysqlConnection;
    MYSQL *connectionPtr;
    MYSQL_RES *lastQueryResult = nullptr;
    bool isConnectedFlag = false;

    // Checks if the database connection is active.
    bool isConnected() const;

    // Asserts that the database connection is established.
    void assertConnection() const;

    // Executes a raw SQL query and returns the number of affected rows.
    long executeRawQuery(const char *query);

    // Retrieves the last error message from the database.
    std::string getLastError() const;
};

