            std::cin >> bookTitle;

            for (int i = 0; i < BookCount; ++i) {
                if (strcmp(bookPointer[i]->getTitle(), bookTitle) == 0) {
                    if (bookPointer[i]->availableCopies > 0) {
                        --(bookPointer[i]->availableCopies);
                        bookPointer[i]->displayDetails();

                        time_t currentTime = time(0);
                        struct tm* now = localtime(&currentTime);
                        Date currentDate(now->tm_mday, now->tm_mon + 1, now->tm_year + 1900);
                        currentCustomer->borrowedBooks[currentCustomer->bookCount] = *bookPointer[i];
                        currentCustomer->issueDates[currentCustomer->bookCount] = currentDate;

                        std::cout << "\n\t\t\t\t\t\tEnter Return Date :";
                        Date returnDate;
                        int errorFlag = 1;

                        while (errorFlag == 1) {
