                                std::cin >> returnDate;
                                errorFlag = 0;
                            } catch (const char* msg) {
                                std::cout << "\n\t\t\t\t\t\tError : " << msg << "\n\n";
                            }
                            if (errorFlag == 0) {
                                int dateDifference = returnDate - currentCustomer->issueDates[currentCustomer->bookCount];
