#include <iostream>
#include <string>

using namespace std;

class Student {
private:
    string name = "Anonymous";
    int age = 0;

    int* grades = nullptr;
    int gradeCount = 0;

public:
    const int id;
    static int studentCount;

public:
    // Constructor with name only, sets default age
    Student(string name) : id(0), age(23) {
        this->name = name;
        Student::studentCount++;
    }

    // Constructor with name and age
    Student(string name, int age) : id(Student::studentCount) {
        this->name = name;
        this->age = age;
        Student::studentCount++;
    }

    // Constructor with age and name
    Student(int age, string name) : id(Student::studentCount) {
        this->name = name;
        this->age = age;
        Student::studentCount++;
    }

    // Constructor with name, age, and number of grades
    Student(string name, int age, int gradeCount) : id(Student::studentCount) {
        this->name = name;
        this->age = age;
        this->gradeCount = gradeCount;
        this->grades = new int[this->gradeCount];
        fill(grades, grades + gradeCount, 0);
        Student::studentCount++;
    }

    // Destructor to clean up dynamically allocated memory
    ~Student() {
        delete[] grades;
    }

    // Copy constructor for deep copy
    Student(const Student& existing) : id(existing.id) {
        this->name = existing.name;
        this->age = existing.age;
        this->gradeCount = existing.gradeCount;
        this->grades = new int[existing.gradeCount];
        copy(existing.grades, existing.grades + existing.gradeCount, this->grades);
    }

    int getAge() const {
        return age;
    }

    int getGradeCount() const {
        return gradeCount;
    }

    int getGrade(int index) const {
        if (index >= 0 && index < gradeCount) {
            return grades[index];
        }
        throw new exception();
    }

    static int getStudentCount() {
        return studentCount;
    }

    string getName() const {
        return name;
    }

    void operator=(const Student& s) {
        this->name = s.name;
        this->age = s.age;
        this->gradeCount = s.gradeCount;

        delete[] this->grades;
        this->grades = new int[s.gradeCount];
        copy(s.grades, s.grades + s.gradeCount, this->grades);
    }

    void operator-=(int gradesToRemove) {
        if (gradesToRemove <= gradeCount) {
            int* newGrades = new int[gradeCount - gradesToRemove];
            copy(grades, grades + gradeCount - gradesToRemove, newGrades);
            delete[] grades;
            grades = newGrades;
            gradeCount -= gradesToRemove;
        } else {
            throw new exception();
        }
    }

    float getAverage() const {
        float average = 0;
        for (int i = 0; i < gradeCount; i++) {
            average += grades[i];
        }
        return (average / gradeCount);
    }

    bool operator==(const Student& other) const {
        return this->name.compare(other.name) == 0;
    }

    explicit operator float() const {
        return getAverage();
    }

    explicit operator int() const {
        return age;
    }

    int operator()(int min, int max) const {
        int count = 0;
        for (int i = 0; i < gradeCount; i++) {
            if (grades[i] >= min && grades[i] <= max) {
                count++;
            }
        }
        return count;
    }

    int& operator[](int index) {
        if (index >= 0 && index < gradeCount) {
            return grades[index];
        }
        throw new exception();
    }

    // Pre-increment operator
    Student operator++() {
        age++;
        return *this;
    }

    // Post-increment operator
    Student operator++(int) {
        Student copy = *this;
        age++;
        return copy;
    }

    friend Student operator+(Student& student, int grade);
    friend void operator>>(istream& in, Student& student);
};

int Student::studentCount = 0;

Student operator+(Student& student, int grade) {
    Student result = student;
    int* newGrades = new int[result.getGradeCount() + 1];
    copy(result.grades, result.grades + result.getGradeCount(), newGrades);
    newGrades[result.gradeCount] = grade;

    delete[] result.grades;
    result.grades = newGrades;
    result.gradeCount++;

    return result;
}

Student operator+(int grade, Student& student) {
    return student + grade;
}

ostream& operator<<(ostream& out, const Student& student) {
    out << endl << "----------------------------";
    out << endl << "Name: " << student.getName();
    out << endl << "Age: " << student.getAge();
    out << endl << "ID: " << student.id;
    out << endl << "Grades:";
    for (int i = 0; i < student.getGradeCount(); i++) {
        out << " " << student.getGrade(i);
    }
    return out;
}

void operator>>(istream& in, Student& student) {
    cout << endl << "New student name: ";
    in >> student.name;
    cout << "New age: ";
    in >> student.age;

    delete[] student.grades;

    cout << endl << "New number of grades: ";
    in >> student.gradeCount;

    student.grades = new int[student.gradeCount];
    for (int i = 0; i < student.gradeCount; i++) {
        cout << "Grade " << i + 1 << ": ";
        in >> student.grades[i];
    }
}

bool operator>(const Student& student1, const Student& student2) {
    return student1.getAverage() > student2.getAverage();
}

bool operator!(const Student& student) {
    for (int i = 0; i < student.getGradeCount(); i++) {
        if (student.getGrade(i) < 5) {
            return true;
        }
    }
    return false;
}

