#include <bits/stdc++.h>
using namespace std;

class Matrix {
private:
    int numRows, numCols;
    int **elements;

public:
    // Constructor to initialize matrix dimensions and allocate memory
    Matrix(int rows = 0, int cols = 0) : numRows(rows), numCols(cols) {
        elements = new int*[numRows];
        for (int i = 0; i < numRows; i++) {
            elements[i] = new int[numCols];
        }
    }

    // Destructor to free allocated memory
    ~Matrix() {
        for (int i = 0; i < numRows; i++) {
            delete[] elements[i];
        }
        delete[] elements;
    }

    // Generate a random matrix with dimensions between 1 and 5
    void generateRandomMatrix() {
        srand(time(0));
        numRows = rand() % 5 + 1;
        numCols = rand() % 5 + 1;
        elements = new int*[numRows];
        for (int i = 0; i < numRows; i++) {
            elements[i] = new int[numCols];
            for (int j = 0; j < numCols; j++) {
                elements[i][j] = rand() % 10;
            }
        }
    }

    // Overload the addition operator for matrix addition
    Matrix operator+(const Matrix &other) const {
        if (numRows != other.numRows || numCols != other.numCols) {
            throw invalid_argument("Matrices must have the same dimensions for addition.");
        }
        Matrix result(numRows, numCols);
        for (int i = 0; i < numRows; i++) {
            for (int j = 0; j < numCols; j++) {
                result.elements[i][j] = elements[i][j] + other.elements[i][j];
            }
        }
        return result;
    }

    // Overload the multiplication operator for matrix multiplication
    Matrix operator*(const Matrix &other) const {
        if (numCols != other.numRows) {
            throw invalid_argument("Incompatible matrix dimensions for multiplication.");
        }
        Matrix result(numRows, other.numCols);
        for (int i = 0; i < numRows; i++) {
            for (int j = 0; j < other.numCols; j++) {
                result.elements[i][j] = 0;
                for (int k = 0; k < numCols; k++) {
                    result.elements[i][j] += elements[i][k] * other.elements[k][j];
                }
            }
        }
        return result;
    }

    // Friend functions for input and output stream operations
    friend ostream& operator<<(ostream &os, const Matrix &m);
    friend istream& operator>>(istream &is, Matrix &m);
};

// Output stream operator for displaying the matrix
ostream& operator<<(ostream &os, const Matrix &m) {
    for (int i = 0; i < m.numRows; i++) {
        for (int j = 0; j < m.numCols; j++) {
            os << m.elements[i][j] << " ";
        }
        os << endl;
    }
    return os;
}

// Input stream operator for reading matrix dimensions and elements
istream& operator>>(istream &is, Matrix &m) {
    cout << "Enter number of rows: ";
    is >> m.numRows;
    cout << "Enter number of columns: ";
    is >> m.numCols;

    // Free previously allocated memory before reallocating
    for (int i = 0; i < m.numRows; i++) {
        delete[] m.elements[i];
    }
    delete[] m.elements;

    m.elements = new int*[m.numRows];
    for (int i = 0; i < m.numRows; i++) {
        m.elements[i] = new int[m.numCols];
        for (int j = 0; j < m.numCols; j++) {
            cout << "Enter element [" << i << "][" << j << "]: ";
            is >> m.elements[i][j];
        }
    }
    return is;
}

int main() {
    Matrix matrixA, matrixB;
    cout << "Enter matrix A:" << endl;
    cin >> matrixA;
    cout << "Enter matrix B:" << endl;
    cin >> matrixB;

    // Attempt to add the matrices and handle potential exceptions
    try {
        Matrix matrixC = matrixA + matrixB;
        cout << "Matrix A + B:\n" << matrixC << endl;
    } catch (const invalid_argument &e) {
        cout << e.what() << endl;
    }

    // Attempt to multiply the matrices and handle potential exceptions
    try {
        Matrix matrixD = matrixA * matrixB;
        cout << "Matrix A * B:\n" << matrixD << endl;
    } catch (const invalid_argument &e) {
        cout << e.what() << endl;
    }

    return 0;
}

