int uscln(int a, int b) {
	a = abs(a);
	b = abs(b);

	while (b != 0) {
		int r = a % b;
		a = b;
		b = r;
	}
	return a;
}

class PhanSo {
private: 
	int tu, mau;
public: 
	// Nhap, Xuat 
	PhanSo(int t, int m) {
		tu = t;
		mau = m;
	}

	PhanSo(int t): PhanSo(t,1) {}

	PhanSo():PhanSo(0,1) {
		// PhanSo(0,1)
	}

	void Xuat() {
		cout << tu << "/" << mau << endl;
	}
	void toi_gian(/*PhanSo a*/) {
		int t = uscln(abs(tu), abs(mau));
		tu = tu / t;
		mau = mau / t;
	}

//	PhanSo cong(/*PhanSo a,*/ PhanSo b) 
	PhanSo operator-(/*PhanSo a,*/ PhanSo b) {
		PhanSo kq;
		kq.tu = tu * b.mau - mau * b.tu;
		kq.mau = mau * b.mau;
		kq.toi_gian();

		return kq;
	}

	friend PhanSo operator+(PhanSo a, PhanSo b);

};

PhanSo operator+(PhanSo a, PhanSo b) {
	PhanSo kq;
	kq.tu = a.tu * b.mau + a.mau * b.tu;
	kq.mau = a.mau * b.mau;

	kq.toi_gian();

	return kq;
}

