		if (toH < 0 || toH>7 || toC < 0 || toC > 7) return false;
		if (fromH != toH && fromC != toC) return false;

		if (fromH == toH) {
			if (fromC < toC) {
				for (int c = fromC + 1; c < toC; c++) {
					if (banco.getQuanCo(fromH, c) != NULL) return false;
