			return 0;
		else
		{
			amount += temp;
			return 1;
		}
	}
	int deductAmount(int temp)
	{
		if (state == "dormant")
			return 0;
		else
		{
			if (temp > amount)
				return 3;
			else
			{
				amount -= temp;
				return 1;
			}
		}
	}
