class AbstractClass {
    int value;
public:
    int getConstantValue() {
        return 10;
    }
    virtual int mandatoryFunction(float input) = 0;
};

class DerivedA : public AbstractClass {
    char value;

public:
    DerivedA(int input) {
        // Constructor logic can be added here if needed
    }

    void displayMessage() {
        cout << endl << "Hello from A";
    }

    virtual void displayVirtualMessage() {
        cout << endl << "Hello virtual from A";
    }

    int mandatoryFunction(float input) override {
        return 0;
    }
};

class DerivedB : public DerivedA {
    int values[1000];

public:
    DerivedB() : DerivedA(50) {
        // Initialize the values array to zero
        for (int i = 0; i < 1000; i++)
            this->values[i] = 0;
    }

    void displayMessage() override {
        cout << endl << "Hello from B";
        // Display the 1000 integer values
    }

    void displayMessage(int input) {
        cout << endl << "Hello from B";
        // Display the 1000 integer values
    }

    void displayVirtualMessage() override {
        this->DerivedA::displayVirtualMessage();
        cout << endl << "Hello virtual from B";
        // Display the 1000 integer values
    }

    float calculateAverage() {
        float sum = 0;
        for (int i = 0; i < 1000; i++)
            sum += values[i];
        return sum / 1000;
    }

    // Overloaded logical NOT operator
    bool operator!() {
        return this->calculateAverage() == 0;
    }

    explicit operator float() {
        return this->calculateAverage();
    }

    int overloadedFunction(int input) {
        return input / 10;
    }

    int overloadedFunction(int input1, int input2) {
        return input1 + input2;
    }

    string overloadedFunction(string message, int input) {
        return message + std::to_string(input);
    }
};

// Global overloaded functions
int overloadedFunction(int input) {
    return input / 10;
}

int overloadedFunction(int input1, int input2) {
    return input1 + input2;
}

string overloadedFunction(string message, int input) {
    return message + std::to_string(input);
}

