#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <functional>
#include <memory>

// Abstract base class representing a component in the composite structure
class Component {
public:
    virtual void add(const std::weak_ptr<Component>& component) { /* No implementation for leaf nodes */ }
    virtual void display() const = 0;
    virtual ~Component() {}
};

// Composite class that can contain child components
class Composite : public Component {
public:
    Composite() = default;

    // Adds a child component if it is valid
    void add(const std::weak_ptr<Component>& component) override {
        if (!component.expired()) {
            children.push_back(component);
        }
    }

    // Displays the composite structure
    void display() const override {
        std::cout << " (";
        std::for_each(children.begin(), children.end(), [=](std::weak_ptr<Component> component) {
            if (!component.expired()) {
                component.lock()->display();
            }
        });
        std::cout << ") ";
    }

    ~Composite() {}

private:
    std::vector<std::weak_ptr<Component>> children; // Child components
};

// Leaf class representing an end node in the composite structure
class Leaf : public Component {
public:
    Leaf(const std::string& name) : name(name) {}

    // Displays the name of the leaf
    void display() const override {
        std::cout << "[" << name << "]";
    }

    std::string getName() const { return name; }

    ~Leaf() {}

private:
    std::string name; // Name of the leaf
};

int main() {
    auto group1 = std::make_shared<Composite>();
    auto group2 = std::make_shared<Composite>();
    auto group3 = std::make_shared<Composite>();
    auto leaf1 = std::make_shared<Leaf>("Leaf_1");
    auto leaf2 = std::make_shared<Leaf>("Leaf_2");
    auto leaf3 = std::make_shared<Leaf>("Leaf_3");
    auto leaf4 = std::make_shared<Leaf>("Leaf_4");
    auto leaf5 = std::make_shared<Leaf>("Leaf_5");

    // Constructing the composite structure
    group1->add(leaf1);
    group1->add(group2);

    group2->add(leaf2);
    group2->add(leaf3);

    group3->add(leaf4);
    group2->add(group3);

    // Displaying the composite structures
    group1->display();
    std::cout << "\n";

    group2->display();
    std::cout << "\n";

    group3->display();
    std::cout << "\n";

    leaf5->display();
    std::cout << "\n";

    system("pause");
    return 0;
}

