void updateAccount(int accountNumber) {
    bool found = false;
    Account account;
    std::fstream file("Account.dat", std::ios::binary | std::ios::in | std::ios::out);
    if (!file) {
        std::cout << "File could not be opened! Press any key...";
        return;
    }
    while (file.read(reinterpret_cast<char*>(&account), sizeof(Account)) && !found) {
        if (account.getAccountNumber() == accountNumber) {
            account.displayAccount();
            std::cout << "\n\n==>>Enter The New Details of Account" << std::endl;
            account.updateAccount();
            int pos = (-1) * sizeof(Account);
            file.seekp(pos, std::ios::cur);
            file.write(reinterpret_cast<char*>(&account), sizeof(Account));
            std::cout << "\nRecord Updated..\nPress Enter to continue.";
            found = true;
        }
    }
    file.close();
    if (!found) {
        std::cout << "\nRecord Not Found";
    }
}

void removeAccount(int accountNumber) {
    Account account;
    std::ifstream inFile("Account.dat", std::ios::binary);
    if (!inFile) {
        std::cout << "File could not be opened! Press any key...";
        return;
    }
    std::ofstream outFile("Temp.dat", std::ios::binary);
    while (inFile.read(reinterpret_cast<char*>(&account), sizeof(Account))) {
        if (account.getAccountNumber() != accountNumber) {
            outFile.write(reinterpret_cast<char*>(&account), sizeof(Account));
        }
    }
    inFile.close();
    outFile.close();
    remove("Account.dat");
    rename("Temp.dat", "Account.dat");
    std::cout << "\nAccount Deleted..\nPress Enter to continue.";
}

