// Represents a node in a doubly linked list, containing transaction details.
class Node {
public:
    float amount; // Transaction amount
    int date;     // Transaction date (placeholder for simplicity)
    string description; // Description of the transaction

    Node* next; // Pointer to the next node in the list
    Node* prev; // Pointer to the previous node in the list

    // Default constructor
    Node() {}

    // Constructor for creating a node with specified values and pointers
    Node(float amt, int dt, string desc, Node* previous, Node* nextNode)
        : amount(amt), date(dt), description(desc), prev(previous), next(nextNode) {}

    // Constructor for creating a node with specified values, no pointers
    Node(float amt, int dt, string desc)
        : amount(amt), date(dt), description(desc) {}
};

int main(int argc, char* argv[]) {
    Node* head = new Node(); // Create the head node of the list

    Node* temp = new Node(19.95, 1, "paint", nullptr, nullptr); // Create a new node with transaction details

    head->next = temp; // Link head to the new node
    temp->prev = head; // Link the new node back to head

    // Output the addresses of the nodes
    printf("%p\n", static_cast<void*>(head)); // Address of head node
    printf("%p\n", static_cast<void*>(head->next)); // Address of the next node

    // Output transaction details using C++ style
    cout << temp->amount << ", on " << temp->date << ", Item: " << temp->description << endl;

    return 0; // Indicate successful execution
}

