#include <iostream>

using namespace std;

class CppArray {
private:
    int elements[10];
    int sizeLimit;
    int tempStorage;

public:
    void inputElements();
    void displayElements();
    void sortElements();
    void displayRange();
    void exchangeElements();
    int getSize();
};

// Collects user input for the array elements and sets the size limit
void CppArray::inputElements() {
    cout << "\nEnter the limit of array: ";
    cin >> sizeLimit;

    cout << "\nEnter the array elements: ";
    for (int index = 0; index < sizeLimit; index++) {
        cout << "\na[" << index << "] = ";
        cin >> elements[index];
    }
}

// Displays the elements of the array
void CppArray::displayElements() {
    cout << "\nThe entered array is: ";
    for (int index = 0; index < sizeLimit; index++) {
        cout << "\na[" << index << "] = " << elements[index];
    }
}

// Sorts the array elements in ascending order using bubble sort
void CppArray::sortElements() {
    for (int outerIndex = 0; outerIndex < sizeLimit; outerIndex++) {
        for (int innerIndex = 0; innerIndex < sizeLimit - 1; innerIndex++) {
            if (elements[innerIndex] > elements[innerIndex + 1]) {
                tempStorage = elements[innerIndex + 1];
                elements[innerIndex + 1] = elements[innerIndex];
                elements[innerIndex] = tempStorage;
            }
        }
    }

    cout << "\nThe sorted array is: ";
    for (int index = 0; index < sizeLimit; index++) {
        cout << "\na[" << index << "] = " << elements[index];
    }
}

// Displays the range of the array elements
void CppArray::displayRange() {
    cout << "\nThe range of array is from " << elements[0] << " to " << elements[sizeLimit - 1];
}

// Copies the elements to a new array and displays it
void CppArray::exchangeElements() {
    int exchangedArray[10];
    for (int index = 0; index < sizeLimit; index++) {
        exchangedArray[index] = elements[index];
    }

    cout << "\nThe exchanged array is: ";
    for (int index = 0; index < sizeLimit; index++) {
        cout << "\nb[" << index << "] = " << exchangedArray[index];
    }
}

// Returns the size of the array
int CppArray::getSize() {
    return sizeLimit;
}

int main() {
    int arraySize;
    CppArray arrayObject;

    arrayObject.inputElements();
    arrayObject.displayElements();
    arrayObject.displayRange();
    arrayObject.exchangeElements();
    arrayObject.sortElements();
    arraySize = arrayObject.getSize();

    cout << "\nThe size of array is: " << arraySize;
    return 0;
}

