// Represents a student with a unique identifier and name.
class Student {
public:
    Student(int id, string studentName) : idNumber(id), name(studentName) {}

    // Displays the student's ID and name.
    void display() const {
        cout << "ID: " << idNumber << endl << "Name: " << name << endl;
    }

