    string name;
};

// Represents a student who is also a class monitor, extending the basic Student class.
class MonitoredStudent : public Student {
public:
    MonitoredStudent(int id, string studentName, int monitorId, string monitorName, int studentAge, string studentAddress)
        : Student(id, studentName), monitor(monitorId, monitorName), age(studentAge), address(studentAddress) {}

    // Displays the student's details including age and address.
    void show() const {
        cout << "This student is:" << endl;
        display();
        cout << "Age: " << age << endl;
        cout << "Address: " << address << endl << endl;
    }

    // Displays the details of the class monitor.
    void showMonitor() const {
        cout << endl << "Class monitor is:" << endl;
        monitor.display();
    }

private:
    Student monitor;
    int age;
    string address;
};

int main() {
    MonitoredStudent student1(10010, "Wang_Li", 10001, "Li_jun", 19, "115 Beijing Road, Shanghai");
    student1.show();
    student1.showMonitor();
    return 0;
}

#include<iostream>
//RUNTIME POLYMORPHISM - Virtual functions are used to achieve runtime polymorphism. It is achieved by function overriding(re-defination)
// of base class method which is re-defined in a derived class.

//Then a pointer of type base class is created which refers to derived class object
//and the base method is called , which actually executes the derived class version
//method.
//Dynamic binding is done i.e during runtime 

using namespace std;

class Person {
	public:
		//does runtime binding of intro() based on the type of object is used to invoke the method
		void virtual intro() {
			cout<<"Hello I am a Person"<<endl;
		}
};

class Anish : public Person {
	public:
		void intro() { //function overridden
			cout<<"This is Anish"<<endl;
		}
};

class Mrinal : public Person {
	public:
		void intro() {
			cout<<"Hi this is Mrinal"<<endl;
		}
};


void getIntro(Person &p) {
	p.intro();
}


int main() {

	Person *p1,*p2;
	Anish a;
	Mrinal m;
	p1 = &a;
	p2= &m;
	p2 =  &m;

	//runtime polymorphism
	p1->intro();//intro() method of class Anish called
	p2->intro();//intro() method of class Mrinal called 
//	a.intro();
//	getIntro(a);//without virtual base function , it would have printed the base method value
//	getIntro(m);

	return 0;
}

