// Class responsible for managing the OpenGL window and event handling
class Interface
{
public:
   // Default constructor initializes the window with default parameters
   Interface() { initialize(0, nullptr, "Window"); }

   // Constructor allows custom window parameters
   Interface(int argc, char ** argv, const char * title)
   {
      initialize(argc, argv, title);
   }

   // Destructor for cleanup
   ~Interface();

   // Starts the main loop and sets the callback function for frame updates
   void run(void (*callbackFunction)(const Interface *, void *), void *userData);

   // Key event status retrieval
   int isDown() const { return keyDownStatus; }
   int isUp() const { return keyUpStatus; }
   int isLeft() const { return keyLeftStatus; }
   int isRight() const { return keyRightStatus; }
   int isSpace() const { return keySpaceStatus; }

   static void *userPointer; // Pointer for client data
   static void (*callbackFunction)(const Interface *, void *); // User-defined callback

   // Sets the frame rate for the rendering loop
   void setFramesPerSecond(double frameRate);

private:
   // Initializes the interface with given parameters
   void initialize(int argc, char ** argv, const char * title);

   // Checks if it's time to redraw the screen
   bool isTimeToDraw();

   // Updates the next draw time based on the current time
   void setNextDrawTime();

   // Retrieves the time for the next frame draw
   unsigned int getNextTick() const { return nextTickTime; }

   // Key event callbacks
   friend void keyDownCallback(int key, int x, int y);
   friend void keyUpCallback(int key, int x, int y);
   friend void keyboardCallback(unsigned char key, int x, int y);
   friend void keyboardUpCallback(unsigned char key, int x, int y);
   friend void drawCallback();

   // Retrieves the current frame rate
   double frameRate() const { return frameTimeInterval; }

   // Static members for managing state and timing
   static bool initialized; // Ensures constructor runs only once
   static double frameTimeInterval; // Time interval between frames
   static unsigned int nextTickTime; // Time of the next frame draw

   // Key press status
   static int keyDownStatus; // Down arrow key status
   static int keyUpStatus; // Up arrow key status
   static int keyLeftStatus; // Left arrow key status
   static int keyRightStatus; // Right arrow key status
   static int keySpaceStatus; // Space key status
};

