    library[4] = Book("The novel is a nostalgic story of loss and burgeoning sexuality.", "Norwegian Wood", "Haruki Murakami");

    // Simulate student interactions
    for (int i = 0; i < 10; i++) {
        students[i].greet(students[rand() % 10]);
