// Class representing a sample object with a static counter
class Sample {
    int instanceId; // Unique identifier for each instance
    static int instanceCounter; // Static counter for tracking instances

public:
    // Constructor that initializes the instance ID and logs its creation
    Sample() {
        instanceId = ++instanceCounter;
        cout << "Constructor called: " << instanceId << endl;
    }

    // Destructor that logs when an instance is destroyed
    ~Sample() {
        cout << "Destructor called: " << instanceId << endl;
    }
};

// Static member variable initialization
int Sample::instanceCounter = 0;

// Main function to demonstrate object creation and destruction
int main() {
    Sample firstInstance; // Create first instance
    {
        Sample secondInstance; // Create second instance within a nested scope
        {
            Sample thirdInstance; // Create third instance within another nested scope
        } // thirdInstance goes out of scope here
    } // secondInstance goes out of scope here
