#include <iostream>    // for output
#include <typeinfo>    // for type identification

class Person {
public:
    virtual ~Person() {} // Virtual destructor for proper cleanup in derived classes
};

class Employee : public Person {
    // Employee-specific members can be defined here
};

int main() {
    Person personInstance;
    Employee employeeInstance;
    Person* personPtr = &employeeInstance;
    Person& personRef = employeeInstance;

    // Output the type information of the instances
    std::cout << typeid(personInstance).name() << std::endl;   // Outputs the type of personInstance
    std::cout << typeid(employeeInstance).name() << std::endl; // Outputs the type of employeeInstance
    std::cout << typeid(personPtr).name() << std::endl;        // Outputs the type of personPtr (pointer type)
    std::cout << typeid(*personPtr).name() << std::endl;       // Outputs the dynamic type of the object pointed to by personPtr
    std::cout << typeid(personRef).name() << std::endl;        // Outputs the dynamic type of the object referred to by personRef

    Person* nullPtr = nullptr;
    try {
        typeid(*nullPtr); // This will throw std::bad_typeid, as dereferencing a null pointer is not allowed
    } catch (...) {
        // Handle the exception silently
    }

    Person& nullRef = *nullPtr; // Undefined behavior: dereferencing a null pointer
    typeid(nullRef);            // This does not throw std::bad_typeid due to the nature of typeid

    return 0;
}

#include <iostream>
using namespace std;

class Base
{
    int firstValue, secondValue;

public:
    // Initializes an object without parameters
    Base()
    {
        cout << "Called Default constructor" << endl;
    }

    // Initializes an object with specified values
    Base(int value1, int value2)
    {
        this->firstValue = value1;
        this->secondValue = value2;
    }

    // Initializes an object as a copy of another object
    Base(const Base &source)
    {
        this->firstValue = source.firstValue;
        this->secondValue = source.secondValue;
    }

    // Displays the values of the object
    void display()
    {
        cout << this->firstValue << " " << this->secondValue << endl;
    }
};

int main()
{
    Base defaultObject; // Create an object using the default constructor

    cout << "Parametrized constructor" << endl;
    Base parameterizedObject(5, 6); // Create an object using the parameterized constructor
    parameterizedObject.display();

    cout << "Copy constructor" << endl;
    Base copiedObject = parameterizedObject; // Create a copy of the parameterized object
    copiedObject.display();

    return 0;
}

