};

class Receiver: public virtual  Storable
{
public:
	Receiver()
		{
			cout << "ctor --> Receiver " << endl;
		}
	void write() override
		{
			cout << "Receiver ..." << endl;
		}
};

class Radio: public Receiver, public Transmitter
{
public:
	void write() override
		{
			Transmitter::write();
			Receiver::write();
			cout << "radio info .." << endl;
		}	
};

