#include <iostream>
#include <memory>

// Interface that defines the expected operations for the client
class Target {
public:
	virtual void requestFirst() const = 0;
	virtual void requestSecond() const = 0;
	virtual void requestThird() const = 0;
	virtual void requestFourth() const = 0;
	virtual ~Target() {}
};

// Existing class with a specific interface that needs to be adapted
class Adaptee {
public:
	void specificRequestOne() const {
		std::cout << "Specific request 1" << std::endl;
	}

	void specificRequestTwo() const {
		std::cout << "Specific request 2" << std::endl;
	}

	void specificRequestThree(int value) const {
		std::cout << "Specific request 3 set value = " << value << std::endl;
	}

	void specificRequestFour() const {
		std::cout << "Specific request 4" << std::endl;
	}

	void specificRequestFive() const {
		std::cout << "Specific request 5" << std::endl;
	}

	~Adaptee() {}
};

// Adapter class that bridges the Target interface and the Adaptee's interface
class Adapter : public Target, private Adaptee {
public:
	virtual void requestFirst() const override {
		specificRequestOne();
		specificRequestTwo();
	}

	virtual void requestSecond() const override {
		specificRequestThree(5);
	}

	virtual void requestThird() const override {
		specificRequestThree(10);
	}

	virtual void requestFourth() const override {
		specificRequestFour();
		specificRequestFive();
	}

	virtual ~Adapter() {}
};

int main() {
	std::unique_ptr<Target> target = std::make_unique<Adapter>();
	target->requestFirst();
	target->requestSecond();
	target->requestThird();
	target->requestFourth();

	system("pause");
	return 0;
}

