// Swaps the values of two variables of any type
template<typename T>
void swapValues(T& first, T& second)
{
	T temporary = first;
	first = second;
	second = temporary;
}

// Tests the swap function with character variables
void testSwap()
{
	char grade = 'a';
	char universal = 'b';
	swapValues(grade, universal);
	cout << "grade: " << grade << " universal: " << universal << endl;
}

// Reverses the elements of an array in place
template<typename T>
void reverseArray(T *array, int length)
{
	for (int index = 0; index < length / 2; index++)
	{
		swapValues(array[index], array[length - index - 1]);
	}
}

// Tests the reverse function with an integer array
void testReverse()
{
	int array[] = { 1, 2, 3, 4, 5, 6 };
	reverseArray(array, 6);
	for (int index = 0; index < 6; index++)
	{
		cout << array[index] << " ";
	}
}

