// Class representing a person with overloaded introduction methods
class Person {
public:
    int fixedValue = 10; // Fixed and constant value, cannot be modified

    // Const member function for constant objects
    void introduce() const {
        cout << "This is const introduction" << endl;
    }

    // Non-const member function for non-constant objects
    void introduce() {
        cout << "This is introduction" << endl;
    }
};

int main() {
    Person nonConstPerson; // Non-const instance of Person
    const Person constPerson; // Const instance of Person

    cout << constPerson.fixedValue << endl;
    // constPerson.fixedValue = 20; // Attempting to modify a const member will result in an error

    // Non-const objects can access both const and non-const members
    // Const objects can only call const member functions, but can access non-const variables

    nonConstPerson.introduce(); // Calls the non-const introduce function
    constPerson.introduce(); // Calls the const introduce function

    return 0;
}

