// Function to test dynamic array allocation and average calculation
void testDynamic1() {
    int size;
    cout << "Enter size: ";
    cin >> size;

    double* arr = new double[size]; // Allocate memory for the array
    double avg = 0;

    for (int i = 0; i < size; i++) {
        cin >> arr[i]; // Input values into the array
        avg += arr[i]; // Calculate the sum for average
    }

    cout << avg / size << endl; // Output the average
    delete[] arr; // Free allocated memory
}

// Function to test dynamic matrix allocation and transposition
void testDynamic2() {
    int size;
    cout << "Enter size: ";
    cin >> size;

    double** matrix = new double*[size]; // Allocate memory for the matrix
    for (int i = 0; i < size; i++) {
        matrix[i] = new double[size]; // Allocate memory for each row
        for (int j = 0; j < size; j++) {
            cin >> matrix[i][j]; // Input values into the matrix
        }
    }

    // Transpose the matrix
    for (int i = 0; i < size; i++) {
        for (int j = i + 1; j < size; j++) {
            double tmp = matrix[j][i];
            matrix[j][i] = matrix[i][j];
            matrix[i][j] = tmp;
        }
    }

    // Output the transposed matrix
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < size; j++) {
            cout << matrix[i][j] << ' ';
        }
        cout << endl;
    }

    // Free allocated memory for the matrix
    for (int i = 0; i < size; i++) {
        delete[] matrix[i];
    }
    delete[] matrix;
}

