int checkPackageExistence(const char packageName[], int& serialNumber) {
    Package tempPackage;
    int found = 0;
    fstream file;
    serialNumber = 0;

    file.open("PACKAGES.TXT", ios::in | ios::binary);
    file.read(reinterpret_cast<char*>(&tempPackage), sizeof(tempPackage));

    if (file.fail()) {
        file.close();
        return found; // File is empty
    }

    while (!file.eof()) {
        if (strcmp(packageName, tempPackage.getName()) == 0) {
            found = 1;
            break;
        }
        serialNumber = tempPackage.getSerialNumber();
        file.read(reinterpret_cast<char*>(&tempPackage), sizeof(tempPackage));
    }
    file.close();
    return found;
}

