void bookTicket() {
    int serialNumber, found = 0;
    float netFare = 0;
    char confirmation;
    int checkNumber = getCurrentCheckNumber();
    Customer customerInstance;
    Package packageInstance;

    cout << "\nEnter Serial Number of the package : ";
    cin >> serialNumber;

    fstream searchFile;
    searchFile.open("PACKAGES.TXT", ios::in | ios::binary);
    searchFile.read(reinterpret_cast<char*>(&packageInstance), sizeof(packageInstance));

    while (!searchFile.eof()) {
        if (serialNumber == packageInstance.getSerialNumber()) {
            found = 1;
            cout << endl;
            packageInstance.display();
            cout << endl;
            drawLine(40, '-');
            break;
        }
        searchFile.read(reinterpret_cast<char*>(&packageInstance), sizeof(packageInstance));
    }
    searchFile.close();

    if (found == 0) {
        cout << "\tPackage not found";
        return;
    }

    fstream bookingsFile;
    bookingsFile.open("BOOKINGS.TXT", ios::app | ios::binary);
    do {
        customerInstance.accept(++checkNumber, packageInstance.getName());
        cout << "\n\nDo you want to confirm the above details? [Y/N] : ";
        cin >> confirmation;
        confirmation = toupper(confirmation);

        if (confirmation == 'Y') {
            netFare = packageInstance.getPrice() * (customerInstance.getTotalMembers() - customerInstance.getChildCount());
            netFare += packageInstance.getPrice() * customerInstance.getChildCount() / 2;
            customerInstance.setTotalFare(netFare);
            bookingsFile.write(reinterpret_cast<char*>(&customerInstance), sizeof(customerInstance));
        } else {
            cout << "\n\nEnter again";
        }
    } while (confirmation != 'Y');
    bookingsFile.close();
}

void cancelTicket() {
    system("cls");
    cout << "*\tCANCEL A TICKET\t*";
    int checkNumber;
    cout << "\nEnter the 5 digit CHK number : ";
    cin >> checkNumber;
    char confirmation;
    Customer customerInstance;
    int found = 0;
    fstream file1, file2;

    file1.open("BOOKINGS.TXT", ios::in | ios::binary);
    file2.open("Temp2.txt", ios::out | ios::trunc | ios::binary);
    file1.read(reinterpret_cast<char*>(&customerInstance), sizeof(customerInstance));

