using namespace std;

class StringManipulator
{
    char *content;
    int size;

public:
    // Constructor initializes an empty string
    StringManipulator()
    {
        size = 0;
        content = new char[size + 1];
    }

    // Constructor initializes with a given C-string
    StringManipulator(const char *input)
    {
        size = strlen(input);
        content = new char[size + 1];
        strcpy(content, input);
    }

    // Displays the content of the string
    void display() const
    {
        cout << content << endl;
    }

    // Concatenates two StringManipulator objects into the current instance
    void concatenate(const StringManipulator &first, const StringManipulator &second)
    {
        size = first.size + second.size;
        delete[] content; // Free existing memory
        content = new char[size + 1];
        strcpy(content, first.content);
        strcat(content, second.content);
    }

    // Destructor to free allocated memory
    ~StringManipulator()
    {
        delete[] content;
    }
};

int main()
{
    StringManipulator name1("Joseph");
    StringManipulator name2("Louis");
    StringManipulator name3("Lagrange");
    StringManipulator combined1, combined2;

    // Combine first two names
    combined1.concatenate(name1, name2);
    // Combine the result with the third name
    combined2.concatenate(combined1, name3);

    // Display all names
    name1.display();
    name2.display();
    name3.display();
    combined1.display();
    combined2.display();

    return 0;
}

