#ifndef EDGE_HPP
#define EDGE_HPP

#include <string>
#include "Synch_queue.hpp"

class Edge {
public:
    // Default constructor
    Edge() = default;

    // Parameterized constructor for initializing edge properties
    Edge(int id, int weight, Synch_queue* messageQueue, const std::string& address, const std::string& port)
        : index(id), weight(weight), mq(messageQueue), ip_address(address), tcp_port(port) {}

    // Copy constructor for creating a duplicate edge
    Edge(const Edge& other)
        : index(other.index), weight(other.weight), mq(other.mq), ip_address(other.ip_address), tcp_port(other.tcp_port) {}

    // Move constructor for transferring ownership of resources
    Edge(Edge&& other) noexcept
        : index(other.index), weight(other.weight), mq(other.mq), ip_address(other.ip_address), tcp_port(other.tcp_port) {
        // Ownership of message queue is transferred; other.mq remains unchanged
    }

    // Accessor for edge weight
    int get_weight() const { return weight; }

    // Accessor for edge index
    int get_index() const { return index; }

    // Accessor for IP address of the target node
    std::string get_ip_address() const { return ip_address; }

    // Accessor for TCP port of the target node
    std::string get_tcp_port() const { return tcp_port; }

private:
    int index;                         // Index of the target node
    int weight;                        // Weight of the edge
    std::string ip_address;            // IP address of the target node's handler thread
    std::string tcp_port;              // TCP port of the target node's handler thread
    Synch_queue* mq;                   // Associated message queue for this edge
};

#endif // EDGE_HPP

