#include <iostream>

class Coordinate {
private:
    float x, y, z;

public:
    Coordinate() : x(0), y(0), z(0) {}
    Coordinate(float xValue, float yValue, float zValue);

    friend void addCoordinates(const Coordinate& first, const Coordinate& second);
    friend void subtractCoordinates(const Coordinate& first, const Coordinate& second);
    friend Coordinate operator+(const Coordinate& first, const Coordinate& second);
    friend Coordinate operator-(const Coordinate& first, const Coordinate& second);
};

Coordinate operator+(const Coordinate& first, const Coordinate& second) {
    Coordinate result;
    result.x = first.x + second.x;
    result.y = first.y + second.y;
    result.z = first.z + second.z;
    return result;
}

Coordinate operator-(const Coordinate& first, const Coordinate& second) {
    Coordinate result;
    result.x = first.x - second.x;
    result.y = first.y - second.y;
    result.z = first.z - second.z;
    return result;
}

Coordinate::Coordinate(float xValue, float yValue, float zValue) 
    : x(xValue), y(yValue), z(zValue) {}

void addCoordinates(const Coordinate& first, const Coordinate& second) {
    Coordinate result = first + second;
    std::cout << "Addition:\n" << result.x << ", " << result.y << ", " << result.z << std::endl;
}

void subtractCoordinates(const Coordinate& first, const Coordinate& second) {
    Coordinate result = first - second;
    std::cout << "Difference:\n" << result.x << ", " << result.y << ", " << result.z << std::endl;
}

int main() {
    float x, y, z;

    std::cout << "Enter first x, y and z coordinates: ";
    std::cin >> x >> y >> z;
    Coordinate firstCoordinate(x, y, z);

    std::cout << "Enter second x, y and z coordinates: ";
    std::cin >> x >> y >> z;
    Coordinate secondCoordinate(x, y, z);

    addCoordinates(firstCoordinate, secondCoordinate);
    subtractCoordinates(firstCoordinate, secondCoordinate);

    return 0;
}

