    // Class to manage error messages and their state
    class ErrorState {
        char* errorMessage; // Pointer to the error message

    public:		
        // Constructor initializes the error message
        explicit ErrorState(const char* message = nullptr);

        // Disable copy constructor
        ErrorState(const ErrorState& other) = delete;

        // Disable copy assignment operator
        ErrorState& operator=(const ErrorState& other) = delete;

        // Destructor to clean up allocated memory
        ~ErrorState();

        // Conversion operator to check if there is an error
        operator bool() const;

        // Assignment operator to set the error message
        ErrorState& operator=(const char* message);

        // Set a new error message
        void message(const char* message);

        // Retrieve the current error message
        const char* message() const;
    };

    // Overload the output stream operator for ErrorState
    std::ostream& operator<<(std::ostream& os, const ErrorState& errorState);
}

