#include <iostream>
#include <cstring>

using namespace std;

class Bank {
    char accountHolderName[50];
    char mobileNumber[11];
    char depositChoice, withdrawChoice;
    int currentBalance = 0;

public:
    void openAccount();
    int depositMoney();
    int withdrawMoney();
    void displayCurrentAmount();
    void showAccountDetails();
    void exitSystem();
};

void Bank::openAccount() {
    cout << "\n Enter Your Full Name: ";
    cin >> accountHolderName;

    cout << "\n Enter Your Mobile Number: ";
    cin >> mobileNumber;

    // Validate mobile number length
    while (strlen(mobileNumber) != 11) {
        cout << "Your Mobile Number Is Invalid. Please Try Again: ";
        cin >> mobileNumber;
    }

    cout << "\n To Open Your Account, Deposit Amount (> 500): ";
    cin >> currentBalance;

    // Ensure minimum deposit requirement
    while (currentBalance < 500) {
        cout << "\n Add " << 500 - currentBalance << " More Balance: ";
        int additionalDeposit;
        cin >> additionalDeposit;
        currentBalance += additionalDeposit;
    }

    cout << "\n Your Balance Is: " << currentBalance;
    cout << "Your Account Is Successfully Created \n";
}

int Bank::depositMoney() {
    // Loop until user decides to stop depositing
    while (depositChoice != 'N') {
        cout << "How Much Money Would You Like To Deposit: ";
        int depositAmount;
        cin >> depositAmount;

        currentBalance += depositAmount;
        cout << "\nYour Current Balance Is: " << currentBalance;
        cout << "\nIf You Want To Deposit More Money, Press Y (Yes) Otherwise N (No): ";
        cin >> depositChoice;
    }
    return 0;
}

int Bank::withdrawMoney() {
    // Loop until user decides to stop withdrawing
    while (withdrawChoice != 'N') {
        cout << "\nYour Current Balance Is: " << currentBalance;
        cout << "How Much Money Would You Like To Withdraw: ";
        int withdrawalAmount;
        cin >> withdrawalAmount;

        if (withdrawalAmount > currentBalance) {
            cout << "Your Balance Is Insufficient \n";
            break;
        } else {
            currentBalance -= withdrawalAmount;
            cout << "\n Your Transaction Is Successful. Your Current Balance Is: " << currentBalance;
            cout << "If You Want To Withdraw More Money, Press Y (Yes) Otherwise Press N (No): ";
            cin >> withdrawChoice;
        }
    }
    return 0;
}

void Bank::displayCurrentAmount() {
    cout << "Your Current Amount In Your Account Is: " << currentBalance;
}

void Bank::showAccountDetails() {
    cout << "\n Account Holder Name: " << accountHolderName;
    cout << "\n Mobile Number: " << mobileNumber;
}

void Bank::exitSystem() {
    cout << "\n Thank You For Using Our Service.";
    cout << "\n Best Of Luck!";
}

