#ifndef __MYITERATOR_H__
#define __MYITERATOR_H__
#include <iostream>
using namespace std;

// Abstract base class for iterators
class Iterator
{
public:
    virtual void First() = 0;
    virtual void Last() = 0;
    virtual void Next() = 0;
    virtual void Previous() = 0;
    virtual bool IsDone() = 0;
    virtual char& CurrentItem() = 0;
};

// Iterator for strings
class StringIterator : public Iterator
{
private:
    char* stringData;
    long currentIndex;

public:
    StringIterator();
    StringIterator(char* inputString, long startIndex = 0);
    StringIterator& operator=(StringIterator& otherIterator);
    virtual void First() override;
    virtual void Last() override;
    virtual void Next() override;
    virtual void nNext(size_t n);
    virtual void Previous() override;
    virtual void nPrevious(size_t n);
    virtual bool IsDone() override;
    virtual char& CurrentItem() override;
    virtual size_t get_Current();
};

//------------------------------------------------------------------------------------------------------------------

// Constant string iterator
class ConstStringIterator : public StringIterator
{
public:
    ConstStringIterator() : StringIterator() {};
    ConstStringIterator(char* inputString, long startIndex = 0) : StringIterator(inputString, startIndex) {};
    ConstStringIterator(const ConstStringIterator& otherIterator) : StringIterator(otherIterator) {};

    ConstStringIterator& operator=(const ConstStringIterator& other)
    {
        StringIterator::StringIterator(other);
        return *this;
    }

    ConstStringIterator& operator++()
    {
        Next();
        return *this;
    }

    ConstStringIterator operator++(int)
    {
        ConstStringIterator temp(*this);
        operator++();
        return temp;
    }

    ConstStringIterator& operator--()
    {
        Previous();
        return *this;
    }

    ConstStringIterator operator--(int)
    {
        ConstStringIterator temp(*this);
        operator--();
        return temp;
    }

    ConstStringIterator operator+(size_t n)
    {
        ConstStringIterator temp(*this);
        temp.nNext(n);
        return temp;
    }

    ConstStringIterator operator-(size_t n)
    {
        ConstStringIterator temp(*this);
        temp.nPrevious(n);
        return temp;
    }

    bool operator==(const ConstStringIterator& rhs) const
    {
        return CurrentItem() == rhs.CurrentItem();
    }

    bool operator!=(const ConstStringIterator& rhs) const
    {
        return CurrentItem() != rhs.CurrentItem();
    }

    char operator*()
    {
        if (IsDone())
        {
            throw;
        }
        return CurrentItem();
    }
};

// Mutable string iterator
class MyStringIterator : public ConstStringIterator
{
public:
    MyStringIterator() : ConstStringIterator() {};
    MyStringIterator(char* inputString, long startIndex = 0) : ConstStringIterator(inputString, startIndex) {};
    MyStringIterator(const MyStringIterator& otherIterator) : ConstStringIterator(otherIterator) {}

    MyStringIterator& operator=(MyStringIterator& other)
    {
        ConstStringIterator::operator=(other);
        return *this;
    }

    char& operator*()
    {
        if (IsDone())
        {
            throw;
        }
        return CurrentItem();
    }
};

//------------------------------------------------------------------------------------------------------------------

// Constant reverse string iterator
class ConstReverseStringIterator : public StringIterator
{
public:
    ConstReverseStringIterator() : StringIterator() {};
    ConstReverseStringIterator(char* inputString, long startIndex) : StringIterator(inputString, startIndex) {};
    ConstReverseStringIterator(const ConstReverseStringIterator& otherIterator) : StringIterator(otherIterator) {};

    ConstReverseStringIterator& operator=(const ConstReverseStringIterator& other)
    {
        StringIterator::StringIterator(other);
