constexpr int MAX_BOOKS = 16;
constexpr int MAX_STUDENTS = 32;

string generateRandomString() {
    string result;
    int length = rand() % 16 + 1;
    while (--length) {
        result += 'A' + rand() % 26;
    }
    return result;
}

class Book {
public:
    string title;
    string author;
    string content;

    Book(const string& title, const string& author, const string& content);
};

class Student {
public:
    string name;
    string major;
    int age;
    int studentNumber;

    Student(const string& name, int age, int studentNumber, const string& major);

    void greet(const Student& otherStudent) const {
        cout << "Hi " << otherStudent.name << ", my name is " << this->name << ". Nice to meet you!" << endl;
    }

    void read(const Book& book) const {
        cout << book.title << " written by " << book.author << ". " << endl << "Contents: " << book.content << endl;
    }

    Book* createBook() const {
        return new Book(generateRandomString(), this->name, generateRandomString());
    }

    void recommendBook(const Student& otherStudent, const Book& book) const {
        cout << otherStudent.name << ", please read " << book.title << ", written by " << book.author << endl;
        otherStudent.read(book);
    }
};

static Book* books[MAX_BOOKS];
static Student* students[MAX_STUDENTS];

Book::Book(const string& title, const string& author, const string& content) 
    : title(title), author(author), content(content) {
    static int bookCount = 0;
    books[bookCount++] = this;
}

Student::Student(const string& name, int age, int studentNumber, const string& major) 
    : name(name), age(age), studentNumber(studentNumber), major(major) {
    static int studentCount = 0;
    students[studentCount++] = this;
}

int main() {
    srand(static_cast<unsigned int>(time(nullptr)));

    for (int i = 0; i < MAX_STUDENTS; ++i) {
        new Student(generateRandomString(), rand() % 10 + 18, 2016000 + rand() % 1000, generateRandomString());
    }

    for (int i = 0; i < MAX_BOOKS - 5; ++i) {
        new Book(generateRandomString(), generateRandomString(), generateRandomString());
    }

    for (int i = 0; i < MAX_STUDENTS; ++i) {
        students[i]->greet(*students[rand() % MAX_STUDENTS]);
    }

    for (int i = 0; i < 5; ++i) {
        students[rand() % MAX_STUDENTS]->createBook();
    }

    for (int i = 0; i < MAX_STUDENTS; ++i) {
        students[i]->read(*books[rand() % MAX_BOOKS]);
    }
}

