// Class representing a product in the supermarket
class Product {
    int productNumber;
    char productName[50];
    float productPrice, quantity, tax, discount;

public:
    void createProduct() {
        productNumber = productCounter;
        cout << "\nProduct number is: " << productNumber;
        getch(); 
        productCounter++;

        cout << "\n\nPlease Enter The Name of The Product: ";
        gets(productName);
        cout << "\nPlease Enter The Price of The Product: ";
        cin >> productPrice;
        cout << "\nPlease Enter The Discount (%): ";
        cin >> discount;
    }

    void showProduct() {
        cout << "\nThe Product No. of The Product: " << productNumber;
        cout << "\nThe Name of The Product: ";
        puts(productName);
        cout << "\nThe Price of The Product: " << productPrice;
        cout << "\nDiscount: " << discount;
    }

    int getProductNumber() { return productNumber; }
    float getProductPrice() { return productPrice; }
    char* getProductName() { return productName; }
    int getDiscount() { return discount; }
}; // End of Product class

Product productInstance;

// Function to write a new product to the file
void writeProduct() {
    fileStream.open("Shop.dat", ios::out | ios::app);
    productInstance.createProduct();
    fileStream.write((char*)&productInstance, sizeof(Product));
    fileStream.close();
    cout << "\n\nThe Product Has Been Created ";
    getch();
}

// Function to display all products from the file
void displayAllProducts() {
    clrscr();
    cout << "\n\n\n\t\tDISPLAY ALL RECORD !!!\n\n";
    fileStream.open("Shop.dat", ios::in);
    while (fileStream.read((char*)&productInstance, sizeof(Product))) {
        productInstance.showProduct();
        cout << "\n\n====================================\n";
        getch();
    }
    fileStream.close();
    getch();
}

// Function to display a specific product based on its number
void displaySpecificProduct(int productNumber) {
    int foundFlag = 0;
    fileStream.open("Shop.dat", ios::in);
    while (fileStream.read((char*)&productInstance, sizeof(Product))) {
        if (productInstance.getProductNumber() == productNumber) {
            clrscr();
            productInstance.showProduct();
            foundFlag = 1;
        }
    }
    fileStream.close();
    if (foundFlag == 0) {
        cout << "\n\nRecord does not exist";
    }
    getch();
}

// Function to modify an existing product's details
void modifyProduct() {
    int productNumber, foundFlag = 0;
    clrscr();
    cout << "\n\n\tTo Modify ";
    cout << "\n\n\tPlease Enter The Product No. of The Product: ";
    cin >> productNumber;
    fileStream.open("Shop.dat", ios::in | ios::out);
    while (fileStream.read((char*)&productInstance, sizeof(Product)) && foundFlag == 0) {
        if (productInstance.getProductNumber() == productNumber) {
            productInstance.showProduct();
            cout << "\nPlease Enter The New Details of Product" << endl;
            productInstance.createProduct();
            int position = -1 * sizeof(productInstance);
            fileStream.seekp(position, ios::cur);
            fileStream.write((char*)&productInstance, sizeof(Product));
            cout << "\n\n\t Record Updated";
            foundFlag = 1;
        }
    }
    fileStream.close();
    if (foundFlag == 0) {
        cout << "\n\n Record Not Found ";
    }
    getch();
}

// Function to delete a product record
void deleteProduct() {
    int productNumber;
    clrscr();
    cout << "\n\n\n\tDelete Record";
    cout << "\n\nPlease Enter The Product No. of The Product You Want To Delete: ";
    cin >> productNumber;
    fileStream.open("Shop.dat", ios::in | ios::out);
    fstream tempFile;
    tempFile.open("Temp.dat", ios::out);
    fileStream.seekg(0, ios::beg);
    while (fileStream.read((char*)&productInstance, sizeof(Product))) {
        if (productInstance.getProductNumber() != productNumber) {
            tempFile.write((char*)&productInstance, sizeof(Product));
        }
    }
    tempFile.close();
    fileStream.close();
    remove("Shop.dat");
    rename("Temp.dat", "Shop.dat");
    cout << "\n\n\tRecord Deleted ..";
    getch();
}

