// Function to place an order and generate an invoice
void placeOrder() {
    int orderArray[50], quantityArray[50], orderCount = 0;
    float amount, discountedAmount, totalAmount = 0;
    char continueOrder = 'Y';
    displayProductMenu();
    cout << "\n============================";
    cout << "\n PLACE YOUR ORDER";
    cout << "\n============================\n";
    do {
        cout << "\n\nEnter The Product No. Of The Product: ";
        cin >> orderArray[orderCount];
        cout << "\nQuantity in number: ";
        cin >> quantityArray[orderCount];
        orderCount++;
        cout << "\nDo You Want To Order Another Product? (y/n): ";
        cin >> continueOrder;
    } while (continueOrder == 'y' || continueOrder == 'Y');

    cout << "\n\nThank You For Placing The Order";
    getch();
    clrscr();
    cout << "\n\n********************************INVOICE************************\n";
    cout << "\nPr No.\tPr Name\tQuantity \tPrice \tAmount \tAmount after discount\n";

    for (int i = 0; i < orderCount; i++) {
        fileStream.open("Shop.dat", ios::in);
        fileStream.read((char*)&productInstance, sizeof(Product));
        while (!fileStream.eof()) {
            if (productInstance.getProductNumber() == orderArray[i]) {
                amount = productInstance.getProductPrice() * quantityArray[i];
                discountedAmount = amount - (amount * productInstance.getDiscount() / 100);
                cout << "\n" << orderArray[i] << "\t" << productInstance.getProductName()
                     << "\t" << quantityArray[i] << "\t\t" << productInstance.getProductPrice() << "\t" << amount << "\t\t" << discountedAmount;
                totalAmount += discountedAmount;
            }
            fileStream.read((char*)&productInstance, sizeof(Product));
        }
        fileStream.close();
    }
    cout << "\n\n\t\t\t\t\tTOTAL = " << totalAmount;
    getch();
}

