// Function to display the main menu
void mainmenu() {
    char choice;
    do {
        clrscr();
        cout << "\n\n\n\tMAIN MENU";
        cout << "\n\n\t01. CUSTOMER";
        cout << "\n\n\t02. ADMINISTRATOR";
