        cin >> choice;

        switch (choice) {
            case '1':
                clrscr();
                placeOrder();
                getch();
                break;
            case '2': {
                for (int attempts = 1; attempts < 4; attempts++) {
                    cout << "\n\n\nEnter ADMIN password: ";
                    gets(adminPassword);
                    if (strcmp("supermarket", adminPassword) == 0) {
                        displayAdminMenu();
