// Class responsible for managing a cache of files with a specified replacement policy.
class FileCache final {
 private:
  FileCache();
  unsigned int cache_capacity_ = MAX_CACHE;
  std::unordered_map<std::string, std::unique_ptr<fs::File>> file_cache_{};
