void BankAccount::loadFromDisk(int index) {
    ifstream infile("ACC.DAT", ios::binary);
    infile.seekg(index * sizeof(BankAccount));
    infile.read(reinterpret_cast<char*>(this), sizeof(*this));
}

void BankAccount::loadFromCustomerDisk(int index) {
    ifstream infile("CACC.DAT", ios::binary);
    infile.seekg(index * sizeof(BankAccount));
    infile.read(reinterpret_cast<char*>(this), sizeof(*this));
}

void BankAccount::saveToCustomerDisk() {
    ofstream outfile("CACC.DAT", ios::app | ios::binary);
    outfile.write(reinterpret_cast<char*>(this), sizeof(*this));
}

void BankAccount::saveToDisk() {
    ofstream outfile("ACC.DAT", ios::app | ios::binary);
    outfile.write(reinterpret_cast<char*>(this), sizeof(*this));
}

int BankAccount::getAccountCount() {
    ifstream infile("ACC.DAT", ios::binary);
    infile.seekg(0, ios::end);
    return static_cast<int>(infile.tellg()) / sizeof(BankAccount);
