const int daysInMonth[12] = {31, 28, 31, 30, 31, 30,
                               31, 31, 30, 31, 30, 31};

class Date {
    int day;
    int month;
    int year;

    // Calculates the number of leap years up to the given date
    int calculateLeapYears(Date date) {
        int totalYears = date.year;
        if (date.month <= 2)
            totalYears--;
        return totalYears / 4 - totalYears / 100 + totalYears / 400;
    }

    // Computes the difference in days between two dates
    int calculateDateDifference(Date startDate, Date endDate) {
        long int totalDaysStart = startDate.year * 365 + startDate.day;
        for (int i = 0; i < startDate.month - 1; i++)
            totalDaysStart += daysInMonth[i];
        totalDaysStart += calculateLeapYears(startDate);

        long int totalDaysEnd = endDate.year * 365 + endDate.day;
        for (int i = 0; i < endDate.month - 1; i++)
            totalDaysEnd += daysInMonth[i];
        totalDaysEnd += calculateLeapYears(endDate);

        return (totalDaysStart - totalDaysEnd);
    }

public:
    Date() : day(0), month(0), year(0) {}

    Date(int d, int m, int y) : day(d), month(m), year(y) {}

    // Overloads the subtraction operator to calculate the difference in days
    int operator- (Date &otherDate) {
        return calculateDateDifference(*this, otherDate);
    }

    friend ostream& operator<<(ostream& outputStream, Date& date);
    friend istream& operator>>(istream& inputStream, Date& date);
};

ostream& operator<<(ostream& outputStream, Date& date) {
    outputStream << date.day << "/" << date.month << "/" << date.year;
    return outputStream;
}

// Checks if a given year is a leap year
bool isLeapYear(int year) {
    if (year % 400 == 0)
        return true;
    if (year % 100 == 0)
        return false;
    if (year % 4 == 0)
        return true;
    return false;
}

// Overloads the input operator to read date values
istream& operator>>(istream& inputStream, Date& date) {
    cout << "\n\t\t\t\t\t\tDate  :"; inputStream >> date.day;
    cout << "\n\t\t\t\t\t\tMonth :"; inputStream >> date.month;
    cout << "\n\t\t\t\t\t\tYear  :"; inputStream >> date.year;

    if (date.day < 0 || date.month < 0 || date.year < 0) {
        throw "Negative Date Error";
    } else if (date.month > 12) {
        throw "Invalid Month Error";
    } else if (isLeapYear(date.year) && date.day > 29) {
        throw "Invalid Date Error";
    } else if (date.day > daysInMonth[date.month - 1]) {
        throw "Invalid Date Error";
    }
    return inputStream;
}

