// Function to validate and retrieve an integer input from the user
int getValidatedIntegerInput() {
    int result = 0;
    while (true) {
        try {
            char inputBuffer[20];
            cin >> inputBuffer;
            for (size_t i = 0; i < strlen(inputBuffer); ++i) {
                if (!isdigit(inputBuffer[i])) {
                    throw "\n\n\t\t\t\t\t\tInvalid input\n";
                } else {
                    result = result + (inputBuffer[i] - '0') * pow(10, strlen(inputBuffer) - i - 1);
                }
            }
        } catch (const char* errorMessage) {
            cout << errorMessage;
            cout << "\n\n\t\t\t\t\t\t\tPlease enter again: ";
            continue;
        }
        break;
    }
    return result;
}

