// Class to manage an array of account pointers with bounds checking
class BoundCheckAccountPtrArray {
public:
    // Constructor to initialize the array with a specified length
    explicit BoundCheckAccountPtrArray(int length);

    // Overloaded subscript operator for non-const objects
    ACCOUNT_PTR& operator[](int index);

    // Overloaded subscript operator for const objects
    ACCOUNT_PTR operator[](int index) const;

    // Function to retrieve the length of the array
    int GetArrLen() const;

    // Destructor to clean up allocated memory
    ~BoundCheckAccountPtrArray();

private:
    int arrlen; // Length of the array
    ACCOUNT_PTR* arr; // Pointer to the array of account pointers
};

BoundCheckAccountPtrArray::BoundCheckAccountPtrArray(int length) : arrlen(length) {
    arr = new ACCOUNT_PTR[length];
}

ACCOUNT_PTR& BoundCheckAccountPtrArray::operator[](int index) {
    // Check for out-of-bounds access and handle the error
    if (index < 0 || index >= arrlen) {
        cout << "Array index out of bound exception" << endl;
        exit(1);
    }
    return arr[index];
}

ACCOUNT_PTR BoundCheckAccountPtrArray::operator[](int index) const {
    // Check for out-of-bounds access and handle the error
    if (index < 0 || index >= arrlen) {
        cout << "Array index out of bound exception" << endl;
        exit(1);
    }
    return arr[index];
}

int BoundCheckAccountPtrArray::GetArrLen() const {
    return arrlen;
}

BoundCheckAccountPtrArray::~BoundCheckAccountPtrArray() {
    delete[] arr; // Release allocated memory for the array
}

