char * get_branch(char rollno[])
{
    char arr[3];
    arr[0] = rollno[5];
    arr[1] = rollno[6];
    arr[2] = '\0';

    if(strcmpi(arr,"CO")==0)
        return "COMPUTER SCIENCE";
    else if(strcmpi(arr,"IT")==0)
        return "INFORMATION TECHNOLOGY";
    else if(strcmpi(arr,"BT")==0)
        return "BIO-TECHNOLOGY";
    else if(strcmpi(arr,"EC")==0)
