using namespace std;

// Class representing a sample with two integer attributes
class Sample {
private:
    int firstValue, secondValue;

public:
    // Constructor to initialize the sample with two integers
    Sample(int first, int second) {
        firstValue = first;
        secondValue = second;
    }

    // Retrieve the first integer value
    int getFirstValue() {
        return firstValue;
    }

    // Retrieve the second integer value
    int getSecondValue() {
        return secondValue;
    }
};

int main() {
    // Initialize a 2D array of Sample objects
    Sample samples[4][2] = {
        { Sample(1, 2), Sample(3, 4) },
        { Sample(5, 6), Sample(7, 8) },
        { Sample(9, 10), Sample(11, 12) },
        { Sample(13, 14), Sample(15, 16) }
    };

    // Iterate through each sample and print its values
    for (int i = 0; i < 4; i++) {
        cout << samples[i][0].getFirstValue() << ' ';
