#include <iostream>
#include <memory>

// Interface for implementation classes
class ImplementationInterface {
public:
    virtual void executeOperation(const double& dimension) = 0;
    virtual ~ImplementationInterface() {}
};

// Concrete implementation A
class ConcreteImplementationA : public ImplementationInterface {
public:
    void executeOperation(const double& dimension) override {
        std::cout << "Concrete Implementation A" << std::endl;
    }
    ~ConcreteImplementationA() {}
};

// Concrete implementation B
class ConcreteImplementationB : public ImplementationInterface {
public:
    void executeOperation(const double& dimension) override {
        std::cout << "Concrete Implementation B" << std::endl;
    }
    ~ConcreteImplementationB() {}
};

// Base class defining the abstraction's interface
class AbstractionBase {
public:
    virtual void execute() = 0; // low-level operation
    virtual void performAction(const double& factor) = 0; // high-level action
    virtual ~AbstractionBase() {}
protected:
    std::weak_ptr<ImplementationInterface> implementation;
    AbstractionBase(const std::weak_ptr<ImplementationInterface>& impl) : implementation(impl) {}
};

// Refined abstraction extending the base interface
class RefinedAbstraction : public AbstractionBase {
public:
    RefinedAbstraction(const double& dimension, const std::shared_ptr<ImplementationInterface>& impl)
        : dimension(dimension), AbstractionBase(impl) {}

    // Low-level implementation specific operation
    void execute() override {
        implementation.lock()->executeOperation(dimension);
    }

    // High-level abstraction specific action
    void performAction(const double& factor) override {
        std::cout << "Performing action" << std::endl;
        dimension *= factor;
    }

    ~RefinedAbstraction() {}

private:
    double dimension;
};

// Main function demonstrating the bridge pattern
int main() {
    std::shared_ptr<ImplementationInterface> implementationA = std::make_shared<ConcreteImplementationA>();
    std::shared_ptr<ImplementationInterface> implementationB = std::make_shared<ConcreteImplementationB>();

    std::shared_ptr<AbstractionBase> abstraction = std::make_shared<RefinedAbstraction>(5, implementationA);
    abstraction->execute();
    abstraction->performAction(2);
    abstraction->execute();

    abstraction = std::make_shared<RefinedAbstraction>(10, implementationB);
    abstraction->execute();

    system("pause");
    return 0;
}

