/* HQLOperand class represents different types of operands used in HQL */

HQLOperand::HQLOperand(const KEYWORD keyword) : type(KW) {
    data.kw = keyword;
}

HQLOperand::HQLOperand(const uint64_t fullname) : type(FULLNAME) {
    data.fullname = fullname;
}

HQLOperand::HQLOperand(const number numericValue) : type(NUM) {
    data.num = numericValue;
}

HQLOperand::HQLOperand(COND_OPER::COND_OPER conditionOperator) : type(COOP) {
    data.coop = conditionOperator;
}

HQLOperand::HQLOperand(const string& strValue, OPERAND_TYPE operandType) : type(operandType) {
    data.str = new string(strValue);
}

HQLOperand::HQLOperand(const vector<string>* strArray, OPERAND_TYPE operandType) : type(operandType) {
    data.array = strArray;
}

HQLOperand::HQLOperand(shared_ptr<HQLNode> nodePtr) : type(NODE) {
    node = nodePtr;
}

HQLOperand::HQLOperand(const JSONNode& jsonNode, OPERAND_TYPE operandType) {
    // Determine the type of operand based on the JSON node type
    switch (jsonNode.type()) {
        case JSON_NULL:
            type = NIL;
            break;
        case JSON_STRING:
            type = (operandType == ID) ? ID : STRING;
            data.str = new string((operandType == ID) ? jsonNode.as_string() : "\"" + jsonNode.as_string() + "\"");
            break;
        case JSON_NUMBER:
            type = NUM;
            data.num = jsonNode.as_float();
            break;
        case JSON_BOOL:
            type = BOOL;
            data.boolean = jsonNode.as_bool();
            break;
        case JSON_ARRAY:
        case JSON_NODE:
            // TODO: Handle JSON_ARRAY and JSON_NODE types
            break;
        default:
            type = NIL;
    }
}

HQLOperand::HQLOperand(const HQLOperand& other) {
    type = other.type;
    switch (type) {
        case BOOL:
            data.boolean = other.data.boolean;
            break;
        case NUM:
            data.num = other.data.num;
            break;
        case ID:
        case STRING:
            data.str = new string(*other.data.str);
            break;
        case NODE:
            node = other.node;
            break;
        case COOP:
            data.coop = other.data.coop;
            break;
        case NUM_ARRAY:
        case STR_ARRAY:
        case CONTAINS_ARG:
            data.array = new vector<string>(*other.data.array);
            break;
        case KW:
            data.kw = other.data.kw;
            break;
        case FULLNAME:
            data.fullname = other.data.fullname;
            break;
        default:
            break;
    }
}

HQLOperand::~HQLOperand() {
    switch (type) {
        case ID:
        case STRING:
            delete data.str;
            break;
        case NUM_ARRAY:
        case STR_ARRAY:
        case CONTAINS_ARG:
            delete data.array;
            break;
        case NODE:
            break;
        default:
            break;
    }
}

const HQLOperand& HQLOperand::operator=(const HQLOperand& rhs) {
    if (this == &rhs) return *this;

    type = rhs.type;
    switch (type) {
        case NUM:
            data.num = rhs.data.num;
            break;
        case ID:
        case STRING:
            delete data.str;
            data.str = new string(*rhs.data.str);
            break;
        case NODE:
            node = rhs.node;
            break;
        case COOP:
            data.coop = rhs.data.coop;
            break;
        case NUM_ARRAY:
        case STR_ARRAY:
        case CONTAINS_ARG:
            delete data.array;
            data.array = new vector<string>(*rhs.data.array);
            break;
        case KW:
            data.kw = rhs.data.kw;
            break;
        case FULLNAME:
            data.fullname = rhs.data.fullname;
            break;
        default:
            break;
    }
    return *this;
}

bool HQLOperand::operator<(const HQLOperand& rhs) {
    if (this == &rhs) return false;
    if (this->type != rhs.type) {
        return this->type < rhs.type;
    } else if (type == NODE) {
        return this->as_node()->get_subtype() < rhs.as_node()->get_subtype();
    }
    return this < &rhs;
}

string HQLOperand::as_coop() const {
    switch (data.coop) {
        case COND_OPER::EQ: return "=";
        case COND_OPER::GT: return ">";
        case COND_OPER::LT: return "<";
        case COND_OPER::GE: return ">=";
        case COND_OPER::LE: return "<=";
        case COND_OPER::IN: return "IN";
        case COND_OPER::CONTAINS: return "CONTAINS";
        case COND_OPER::TIME_IN: return "TIME_IN";
        default: return "BAD-COOP";
    }
}

static string array_to_string(const vector<string>* strArray) {
    std::ostringstream output;
    output << "[";
    auto it = strArray->begin();
    size_t size = strArray->size();
    if (size > 1) {
        auto realIt = it++;
        while (it != strArray->end()) {
            output << *realIt << ", ";
            it++;
            realIt++;
        }
        output << *realIt;
    } else if (size == 1) {
        output << *it;
    }
    output << "]";
    return output.str();
}

string HQLOperand::as_code_hql() const {
    switch (type) {
        case ID: return *data.str;
        case NIL: return "null";
        case BOOL: return data.boolean ? "true" : "false";
        case NUM: return num2str(data.num);
        case STRING: return *data.str;
        case NUM_ARRAY:
        case STR_ARRAY: return array_to_string(data.array);
        case CONTAINS_ARG:
            return ((*data.array)[0].size() == 1 && (*data.array)[0][0] == 0) ?
                "EACH BY " + (*data.array)[1] :
                (*data.array)[0] + " BY " + (*data.array)[1];
        case NODE: return node->to_hql();
        case COOP: return as_coop();
        case KW:
            switch (data.kw) {
                case AUTO: return "AUTO";
                case TAUTO: return "*AUTO";
                case EACH: return "EACH";
                default: return "BAD-KW";
            }
        case FULLNAME: return "#" + num2str(data.fullname);
        default: return "BAD-OBJECT";
    }
}

bool HQLOperand::predicate(const HQLOperand& other, const JSONNode& jsonNode) {
    if (type != COOP) {
        return false;
    }

    switch (data.coop) {
        case COND_OPER::EQ:
            return CompareHQLOperandAndJSONNode<COND_OPER::EQ>(other, jsonNode);
        case COND_OPER::GT:
            return CompareHQLOperandAndJSONNode<COND_OPER::GT>(other, jsonNode);
        case COND_OPER::LT:
            return CompareHQLOperandAndJSONNode<COND_OPER::LT>(other, jsonNode);
        case COND_OPER::GE:
            return CompareHQLOperandAndJSONNode<COND_OPER::GE>(other, jsonNode);
        case COND_OPER::LE:
            return CompareHQLOperandAndJSONNode<COND_OPER::LE>(other, jsonNode);
        case COND_OPER::IN: {
            if (other.get_type() == NUM_ARRAY) {
                if (jsonNode.type() == JSON_NUMBER) {
                    string nodeString = num2str(jsonNode.as_int());
                    for (const auto& element : *other.as_str_array()) {
                        if (nodeString == element) return true;
                    }
                    return false;
                }
                return false;
            } else if (other.get_type() == STR_ARRAY) {
                if (jsonNode.type() == JSON_STRING) {
                    string nodeString = jsonNode.as_string();
                    for (const auto& element : *other.as_str_array()) {
                        if (nodeString == element) return true;
                    }
                    return false;
                }
                return false;
            }
            return false;
        }
        case COND_OPER::CONTAINS: {
            string value = other.as_str_array()->at(0);
            string separator = other.as_str_array()->at(1);
            string nodeString = jsonNode.as_string();
            string unit;
            string::size_type start = 0, end = 0;
            while (end != string::npos) {
                end = nodeString.find_first_of(separator, start);
                unit = (end == string::npos) ? nodeString.substr(start) : nodeString.substr(start, end - start);
                start = end + 1;
                if (value == "\"" + unit + "\"") {
                    return true;
                }
            }
            return false;
        }
        case COND_OPER::TIME_IN: {
            if (jsonNode.type() != JSON_NUMBER) return false;
            if (other.get_type() != NUM) return false;
            time_t currentTime = time(NULL);
            return currentTime - other.as_num() <= jsonNode.as_float();
        }
        default:
            return false;
    }
}

/* HQLNode class represents a node in the HQL syntax tree */

HQLNode::HQLNode(NODE_TYPE nodeType, NODE_SUBTYPE nodeSubtype, TARGET_TYPE targetType) 
    : type(nodeType), subtype(nodeSubtype), target(targetType) {
}

HQLNode::HQLNode(const HQLNode& other) 
    : type(other.type), subtype(other.subtype), target(other.target) {
    etype = other.etype;
    atype = other.atype;
    noperand = other.noperand;
    operands = other.operands;
}

HQLNode::~HQLNode() {
}

const HQLNode& HQLNode::operator=(const HQLNode& rhs) {
    if (this == &rhs) return *this;
    etype = rhs.etype;
    type = rhs.type;
    subtype = rhs.subtype;
    target = rhs.target;
    noperand = rhs.noperand;
    operands = rhs.operands;
    return *this;
}

void HQLNode::push_operand(const HQLOperand& operand) {
    operands.push_back(operand);
}

void HQLNode::push_operand(const vector<HQLOperand>& operandList) {
    std::back_insert_iterator<vector<HQLOperand>> backIterator(operands);
    std::copy(operandList.begin(), operandList.end(), backIterator);
}

