// Represents a car product that can be built using the Builder pattern.
class Car {
public:
	void setSeat(const std::string &seat) 
	{
		seatPart = seat;
	}
	void setEngine(const std::string &engine) 
	{
		enginePart = engine;
	}
	void setWheel(const std::string &wheel) 
	{
		wheelPart = wheel;
	}

	friend std::ostream &operator<<(std::ostream &out, const std::unique_ptr<Car> &car)
	{
		return out << " Seat: " << car->seatPart << ", Engine: " << car->enginePart << " and Wheel: " << car->wheelPart;
	}

	Car() = default; // Default constructor
	Car(const Car& car) = delete; // Copy constructor
	Car& operator=(const Car& car) = delete; // Copy assignment operator
	Car(Car&& car) = delete; // Move constructor
	Car& operator=(Car&& car) = delete; // Move assignment operator
	~Car() {} // Destructor

private:
	std::string seatPart;
	std::string enginePart;
	std::string wheelPart;
};

// Abstract interface for creating car parts.
class Builder {
public:
	virtual void buildSeat(const std::unique_ptr<Car> &car) = 0;
	virtual void buildEngine(const std::unique_ptr<Car> &car) = 0;
	virtual void buildWheel(const std::unique_ptr<Car> &car) = 0;

	Builder() = default; // Default constructor
	Builder(const Builder& builder) = delete; // Copy constructor
	Builder(Builder&& builder) = delete; // Move constructor
	virtual ~Builder() {} // Destructor
};

// Concrete builder for luxury cars, implementing the Builder interface.
class LuxuryCarBuilder : public Builder {
public:
	void buildSeat(const std::unique_ptr<Car> &car) override 
	{
		car->setSeat("Luxury Seat");
	}
	void buildEngine(const std::unique_ptr<Car> &car) override 
	{
		car->setEngine("Luxury Engine");
	}
	void buildWheel(const std::unique_ptr<Car> &car) override 
	{
		car->setWheel("Luxury Wheel");
	}

	LuxuryCarBuilder() = default; // Default constructor
	LuxuryCarBuilder(const LuxuryCarBuilder& builder) = delete; // Copy constructor
	LuxuryCarBuilder& operator=(const LuxuryCarBuilder& builder) = delete; // Copy assignment operator
	LuxuryCarBuilder(LuxuryCarBuilder&& builder) = delete; // Move constructor
	LuxuryCarBuilder& operator=(LuxuryCarBuilder&& builder) = delete; // Move assignment operator
	~LuxuryCarBuilder() {} // Destructor
};

// Concrete builder for basic cars, implementing the Builder interface.
class BasicCarBuilder : public Builder {
public:
	void buildSeat(const std::unique_ptr<Car> &car) override 
	{
		car->setSeat("Basic Seat");
	}
	void buildEngine(const std::unique_ptr<Car> &car) override 
	{
		car->setEngine("Basic Engine");
	}
	void buildWheel(const std::unique_ptr<Car> &car) override 
	{
		car->setWheel("Basic Wheel");
	}

	BasicCarBuilder() = default; // Default constructor
	BasicCarBuilder(const BasicCarBuilder& builder) = delete; // Copy constructor
	BasicCarBuilder& operator=(const BasicCarBuilder& builder) = delete; // Copy assignment operator
	BasicCarBuilder(BasicCarBuilder&& builder) = delete; // Move constructor
	BasicCarBuilder& operator=(BasicCarBuilder&& builder) = delete; // Move assignment operator
	~BasicCarBuilder() {} // Destructor
};

// Manages the construction process of a car using a specified builder.
class Director {
public:
	Director(const std::shared_ptr<Builder> &builder) : builderPtr(builder) {}

	void setBuilder(const std::shared_ptr<Builder> &builder) 
	{
		if (!builderPtr.expired()) 
		{
			builderPtr.reset(); // Clear previous builder
		}
		builderPtr = builder;
	}

	std::unique_ptr<Car> construct() 
	{
		auto car = std::make_unique<Car>();
		builderPtr.lock()->buildSeat(car);
		builderPtr.lock()->buildEngine(car);
		builderPtr.lock()->buildWheel(car);
		return car;
	}

	Director(const Director& director) = delete; // Copy constructor
	Director& operator=(const Director& director) = delete; // Copy assignment operator
	Director(Director&& director) = delete; // Move constructor
	Director& operator=(Director&& director) = delete; // Move assignment operator
	~Director() {} // Destructor

private:
	std::weak_ptr<Builder> builderPtr;
};

int main()
{
	auto luxuryBuilder = std::make_shared<LuxuryCarBuilder>();
	Director director(luxuryBuilder);
	auto luxuryCar = director.construct();
	std::cout << "Product car1: " << luxuryCar << std::endl;

	auto basicBuilder = std::make_shared<BasicCarBuilder>();
	director.setBuilder(basicBuilder);
	auto basicCar = director.construct();
	std::cout << "Product car2: " << basicCar << std::endl;

	system("pause");
	return 0;
}

