int check_exist(char pn[],int&sn)
{
	package t;
	int found=0;
	fstream file;
	sn=0;
	file.open("PACKAGES.TXT",ios::in|ios::binary);
	file.read((char*)&t,sizeof(t));
	if(file.fail())      		//file is empty
	{
		file.close();
		return found;
	}
	while(!file.eof())
	{
		if(strcmp(pn,t.return_name())==0)
		{
			found=1;
			break;
		}
		sn=t.return_sno();
		file.read((char*)&t,sizeof(t));
	}
	file.close();
	return found;
}


