/*!
@brief Namespace for Niels Lohmann
@see https://github.com/nlohmann
*/
namespace nlohmann
{

template<class Key>
class FifoMapComparator
{
  public:
    /// Constructor that initializes the key storage pointer
    FifoMapComparator(
        std::unordered_map<Key, std::size_t>* keyStorage,
        std::size_t timestamp = 1)
        : m_timestamp(timestamp),
          m_keyStorage(keyStorage)
    {}

    /*!
    Compares two keys based on their insertion order using the key mapping.
    */
    bool operator()(const Key& lhs, const Key& rhs) const
    {
        const auto lhsTimestamp = m_keyStorage->find(lhs);
        const auto rhsTimestamp = m_keyStorage->find(rhs);

        if (lhsTimestamp == m_keyStorage->end())
        {
            return false; // lhs not found, cannot be smaller than rhs
        }

        if (rhsTimestamp == m_keyStorage->end())
        {
            return true; // rhs not found, lhs is smaller
        }

        return lhsTimestamp->second < rhsTimestamp->second; // Compare timestamps
    }

    void addKey(const Key& key)
    {
        m_keyStorage->insert({key, m_timestamp++});
    }

    void removeKey(const Key& key)
    {
        m_keyStorage->erase(key);
    }

  private:
    template <
        class MapKey,
        class MapT,
        class MapCompare,
        class MapAllocator
        > friend class FifoMap;

  private:
    std::size_t m_timestamp = 1; // Next valid insertion timestamp
    std::unordered_map<Key, std::size_t>* m_keyStorage = nullptr; // Pointer to key-timestamp mapping
};


template <
    class Key,
    class T,
    class Compare = FifoMapComparator<Key>,
    class Allocator = std::allocator<std::pair<const Key, T>>
    > class FifoMap
{
  public:
    using key_type = Key;
    using mapped_type = T;
    using value_type = std::pair<const Key, T>;
    using size_type = std::size_t;
    using difference_type = std::ptrdiff_t;
    using key_compare = Compare;
    using allocator_type = Allocator;
    using reference = value_type&;
    using const_reference = const value_type&;
    using pointer = typename std::allocator_traits<Allocator>::pointer;
    using const_pointer = typename std::allocator_traits<Allocator>::const_pointer;

    using internal_map_type = std::map<Key, T, Compare, Allocator>;

    using iterator = typename internal_map_type::iterator;
    using const_iterator = typename internal_map_type::const_iterator;
    using reverse_iterator = typename internal_map_type::reverse_iterator;
    using const_reverse_iterator = typename internal_map_type::const_reverse_iterator;

  public:
    /// Default constructor
    FifoMap() : m_keyStorage(), m_comparator(&m_keyStorage), m_internalMap(m_comparator) {}

    /// Copy constructor
    FifoMap(const FifoMap &other) 
        : m_keyStorage(other.m_keyStorage), 
          m_comparator(&m_keyStorage, other.m_comparator.m_timestamp), 
          m_internalMap(other.m_internalMap.begin(), other.m_internalMap.end(), m_comparator) {}

    /// Constructor for a range of elements
    template<class InputIterator>
    FifoMap(InputIterator first, InputIterator last)
        : m_keyStorage(), m_comparator(&m_keyStorage), m_internalMap(m_comparator)
    {
        for (auto it = first; it != last; ++it)
        {
            insert(*it);
        }
    }

    /// Constructor for a list of elements
    FifoMap(std::initializer_list<value_type> init) : FifoMap()
    {
        for (const auto& item : init)
        {
            insert(item);
        }
    }


    /*
     * Element access
     */

    /// Access specified element with bounds checking
    T& at(const Key& key)
    {
        return m_internalMap.at(key);
    }

    /// Access specified element with bounds checking
    const T& at(const Key& key) const
    {
        return m_internalMap.at(key);
    }

    /// Access specified element
    T& operator[](const Key& key)
    {
        m_comparator.addKey(key);
        return m_internalMap[key];
    }

    /// Access specified element
    T& operator[](Key&& key)
    {
        m_comparator.addKey(key);
        return m_internalMap[key];
    }


    /*
     * Iterators
     */

    /// Returns an iterator to the beginning
    iterator begin() noexcept
    {
        return m_internalMap.begin();
    }

    /// Returns an iterator to the end
    iterator end() noexcept
    {
        return m_internalMap.end();
    }

    /// Returns an iterator to the beginning
    const_iterator begin() const noexcept
    {
        return m_internalMap.begin();
    }

    /// Returns an iterator to the end
    const_iterator end() const noexcept
    {
        return m_internalMap.end();
    }

    /// Returns an iterator to the beginning
    const_iterator cbegin() const noexcept
    {
        return m_internalMap.cbegin();
    }

    /// Returns an iterator to the end
    const_iterator cend() const noexcept
    {
        return m_internalMap.cend();
    }

    /// Returns a reverse iterator to the beginning
    reverse_iterator rbegin() noexcept
    {
        return m_internalMap.rbegin();
    }

    /// Returns a reverse iterator to the end
    reverse_iterator rend() noexcept
    {
        return m_internalMap.rend();
    }

    /// Returns a reverse iterator to the beginning
    const_reverse_iterator rbegin() const noexcept
    {
        return m_internalMap.rbegin();
    }

    /// Returns a reverse iterator to the end
    const_reverse_iterator rend() const noexcept
    {
        return m_internalMap.rend();
    }

    /// Returns a reverse iterator to the beginning
    const_reverse_iterator crbegin() const noexcept
    {
        return m_internalMap.crbegin();
    }

    /// Returns a reverse iterator to the end
    const_reverse_iterator crend() const noexcept
    {
        return m_internalMap.crend();
    }


    /*
     * Capacity
     */

    /// Checks whether the container is empty
    bool empty() const noexcept
    {
        return m_internalMap.empty();
    }

    /// Returns the number of elements
    size_type size() const noexcept
    {
        return m_internalMap.size();
    }

    /// Returns the maximum possible number of elements
    size_type max_size() const noexcept
    {
        return m_internalMap.max_size();
    }


    /*
     * Modifiers
     */

    /// Clears the contents
    void clear() noexcept
    {
        m_internalMap.clear();
        m_keyStorage.clear();
    }

    /// Insert value
    std::pair<iterator, bool> insert(const value_type& value)
    {
        m_comparator.addKey(value.first);
        return m_internalMap.insert(value);
    }

    /// Insert value
    template<class P>
    std::pair<iterator, bool> insert(P&& value)
    {
        m_comparator.addKey(value.first);
        return m_internalMap.insert(value);
    }

    /// Insert value with hint
    iterator insert(const_iterator hint, const value_type& value)
    {
        m_comparator.addKey(value.first);
        return m_internalMap.insert(hint, value);
    }

    /// Insert value with hint
    iterator insert(const_iterator hint, value_type&& value)
    {
        m_comparator.addKey(value.first);
        return m_internalMap.insert(hint, value);
    }

    /// Insert value range
    template<class InputIt>
    void insert(InputIt first, InputIt last)
    {
        for (const_iterator it = first; it != last; ++it)
        {
            m_comparator.addKey(it->first);
        }

        m_internalMap.insert(first, last);
    }

    /// Insert value list
    void insert(std::initializer_list<value_type> ilist)
    {
        for (const auto& value : ilist)
        {
            m_comparator.addKey(value.first);
        }

        m_internalMap.insert(ilist);
    }

    /// Constructs element in-place
    template<class... Args>
    std::pair<iterator, bool> emplace(Args&& ... args)
    {
        value_type value(std::forward<Args>(args)...);
        m_comparator.addKey(value.first);
        return m_internalMap.emplace(std::move(value));
    }

    /// Constructs element in-place with hint
    template<class... Args>
    iterator emplace_hint(const_iterator hint, Args&& ... args)
    {
        value_type value(std::forward<Args>(args)...);
        m_comparator.addKey(value.first);
        return m_internalMap.emplace_hint(hint, std::move(value));
    }

    /// Remove element at position
    iterator erase(const_iterator pos)
    {
        m_comparator.removeKey(pos->first);
        return m_internalMap.erase(pos);
    }

    /// Remove elements in range
    iterator erase(const_iterator first, const_iterator last)
    {
        for (const_iterator it = first; it != last; ++it)
        {
            m_comparator.removeKey(it->first);
        }

        return m_internalMap.erase(first, last);
    }

    /// Remove elements with key
    size_type erase(const key_type& key)
    {
        size_type result = m_internalMap.erase(key);

        if (result > 0)
        {
            m_comparator.removeKey(key);
        }

        return result;
    }

    /// Swaps the contents with another fifo_map
    void swap(FifoMap& other)
    {
        std::swap(m_internalMap, other.m_internalMap);
        std::swap(m_comparator, other.m_comparator);
        std::swap(m_keyStorage, other.m_keyStorage);
    }


    /*
     * Lookup
     */

    /// Returns the number of elements matching a specific key
    size_type count(const Key& key) const
    {
        return m_internalMap.count(key);
    }

    /// Finds element with specific key
    iterator find(const Key& key)
    {
        return m_internalMap.find(key);
    }

    /// Finds element with specific key
    const_iterator find(const Key& key) const
    {
        return m_internalMap.find(key);
    }

    /// Returns range of elements matching a specific key
    std::pair<iterator, iterator> equal_range(const Key& key)
    {
        return m_internalMap.equal_range(key);
    }

    /// Returns range of elements matching a specific key
    std::pair<const_iterator, const_iterator> equal_range(const Key& key) const
    {
        return m_internalMap.equal_range(key);
    }

    /// Returns an iterator to the first element not less than the given key
    iterator lower_bound(const Key& key)
    {
        return m_internalMap.lower_bound(key);
    }

    /// Returns an iterator to the first element not less than the given key
    const_iterator lower_bound(const Key& key) const
    {
        return m_internalMap.lower_bound(key);
    }

    /// Returns an iterator to the first element greater than the given key
    iterator upper_bound(const Key& key)
    {
        return m_internalMap.upper_bound(key);
    }

    /// Returns an iterator to the first element greater than the given key
    const_iterator upper_bound(const Key& key) const
    {
        return m_internalMap.upper_bound(key);
    }


    /*
     * Observers
     */

    /// Returns the function that compares keys
    key_compare key_comp() const
    {
        return m_comparator;
    }


    /*
     * Non-member functions
     */

    friend bool operator==(const FifoMap& lhs, const FifoMap& rhs)
    {
        return lhs.m_internalMap == rhs.m_internalMap;
    }

    friend bool operator!=(const FifoMap& lhs, const FifoMap& rhs)
    {
        return lhs.m_internalMap != rhs.m_internalMap;
    }

    friend bool operator<(const FifoMap& lhs, const FifoMap& rhs)
    {
        return lhs.m_internalMap < rhs.m_internalMap;
    }

    friend bool operator<=(const FifoMap& lhs, const FifoMap& rhs)
    {
        return lhs.m_internalMap <= rhs.m_internalMap;
    }

    friend bool operator>(const FifoMap& lhs, const FifoMap& rhs)
    {
        return lhs.m_internalMap > rhs.m_internalMap;
    }

    friend bool operator>=(const FifoMap& lhs, const FifoMap& rhs)
    {
        return lhs.m_internalMap >= rhs.m_internalMap;
    }

  private:
    std::unordered_map<Key, std::size_t> m_keyStorage; // Key storage for timestamps
    Compare m_comparator; // Comparator for key ordering
    internal_map_type m_internalMap; // Internal data structure
};

}

