// Represents a point in 2D space
class Point {
public:
    Point(float xCoordinate, float yCoordinate) : x(xCoordinate), y(yCoordinate) {}

    ~Point() {
        cout << "Executing Point destructor" << endl;
    }

private:
    float x;
    float y;
};

// Represents a circle defined by its center point and radius
class Circle : public Point {
public:
    Circle(float centerX, float centerY, float radiusValue) : Point(centerX, centerY), radius(radiusValue) {}

    ~Circle() {
        cout << "Executing Circle destructor" << endl;
    }

private:
    float radius;
};

int main() {
    // Dynamically allocate a Circle object as a Point
    Point* pointPtr = new Circle(2.5, 1.8, 4.5);

    // Dynamically allocate a Circle object
    Circle* circlePtr = new Circle(2.5, 1.8, 4.5);

    delete circlePtr; // Clean up the Circle object
    return 0;
}

