void VehicleData::deleteData(const char *vehicleNumberInput) {
    FeatureManager featureManager;
    int recordCounter = 0;
    ifstream inputFile;
    ofstream tempFile;

    inputFile.open("file1.dat", ios::in | ios::binary);
    if (!inputFile) {
        cout << "\nFile NOT Found";
    } else {
        tempFile.open("tempFile.dat", ios::out | ios::binary);
        inputFile.read(reinterpret_cast<char*>(this), sizeof(*this));
        while (!inputFile.eof()) {
            if (strcmp(vehicleNumberInput, vehicleNumber)) {
                tempFile.write(reinterpret_cast<char*>(this), sizeof(*this)); 
                recordCounter++;
            }
            inputFile.read(reinterpret_cast<char*>(this), sizeof(*this));
        }
        inputFile.close();
        tempFile.close();
        remove("file1.dat");
        rename("tempFile.dat", "file1.dat");
        setCursorPosition(50, 25);
        if (recordCounter == 0) cout << "Unable to Delete";
        else cout << "\n\tDeleted Successfully";
    }

    setCursorPosition(50, 27);
    cout << "\n\tPress any key to continue...";
    getch();
    featureManager.recordVehicle();
}

