class prime

{

    public:

        char cont;

        int i,num,b=0;

        int check()

        {

            b=0;

            for(i=2;i<num;i++)

            {

                    if(num%i == 0)

                    b++;

            }

            if (b == 0)

                std::cout<<num<<" is prime "<<std::endl;

            else

                std::cout<<num<<" is not prime "<<b<<std::endl;

        }

};

