using namespace std;

const int ARRAY_SIZE = 5;

template <typename T>
class Array {
    T elements[ARRAY_SIZE];

public:
    // Accepts user input to populate the array
    void input() {
        for (int index = 0; index < ARRAY_SIZE; index++) {
            cout << "Element " << index + 1 << ": ";
            cin >> elements[index];
        }
    }

    // Sorts the array in ascending order using a simple comparison-based algorithm
    void sort() {
        T temp;
        for (int i = 0; i < ARRAY_SIZE; i++) {
            for (int j = 0; j < ARRAY_SIZE; j++) {
                if (elements[i] < elements[j]) {
                    temp = elements[i];
                    elements[i] = elements[j];
                    elements[j] = temp;
                }
            }
        }
    }

    // Returns the minimum value in the array
    T minimum() {
        return elements[0];
    }

    // Returns the maximum value in the array
    T maximum() {
        return elements[ARRAY_SIZE - 1];
    }
};

int main() {
    Array<int> intArray;
    cout << "Enter the elements of the integer array:" << endl;
    intArray.input();
    intArray.sort();
    cout << "Min = " << intArray.minimum() << endl;
    cout << "Max = " << intArray.maximum() << endl;

    Array<float> floatArray;
    cout << "Enter the elements of the float array:" << endl;
    floatArray.input();
    floatArray.sort();
    cout << "Min = " << floatArray.minimum() << endl;
    cout << "Max = " << floatArray.maximum() << endl;

    return 0;
}

