    virtual void greet()
    {
        cout << "Good Morning";
    }
};

// Lớp kế thừa từ lớp Base, ghi đè các phương thức
class Derived : public Base
{
public:
    // In thông điệp từ lớp kế thừa
    void print() override
    {
        cout << "Derived Function\n";
    }

    // Ghi đè phương thức greet để thay đổi thông điệp chào hỏi
