template <typename FirstType, typename SecondType, typename ThirdType>
class Container
{
	FirstType firstElement;
	SecondType secondElement;
	ThirdType thirdElement;

public:
	Container(FirstType, SecondType, ThirdType);

	template <typename M, typename N, typename P>
	friend ostream& operator<<(ostream&, const Container<M, N, P>&);
	ThirdType getThird(FirstType, SecondType);
};

template <typename FirstType, typename SecondType, typename ThirdType>
Container<FirstType, SecondType, ThirdType>::Container(FirstType first, SecondType second, ThirdType third)
{
	this->firstElement = first;
	this->secondElement = second;
	this->thirdElement = third;
}

template <typename FirstType, typename SecondType, typename ThirdType>
ostream& operator<<(ostream& os, const Container<FirstType, SecondType, ThirdType>& container)
{
	os << container.firstElement << container.secondElement << container.thirdElement;
	return os;
}

template <typename FirstType, typename SecondType, typename ThirdType>
ThirdType Container<FirstType, SecondType, ThirdType>::getThird(FirstType first, SecondType second)
{
	if (this->firstElement == first && this->secondElement == second)
	{
		return this->thirdElement;
	}
	return ThirdType(); // Return a default-constructed object of unknown type
}

