class Fish // Abstract base class for fish types
{
public:
	virtual bool performAction(int&, int&) = 0; // Determines the fish's behavior
	virtual bool isPredator() = 0; // Indicates if the fish is a predator
};

class Predator : public Fish
{
	int maxHungerDuration;
	int currentHungerDuration;

public:
	Predator() : currentHungerDuration(0), maxHungerDuration(100) {}

	bool performAction(int& x, int& y) override
	{
		if (currentHungerDuration == maxHungerDuration)
			return false; // The predator has starved

		currentHungerDuration++;
		x += rand() % 2 - 1; // Random movement in the x direction
		y += rand() % 2 - 1; // Random movement in the y direction
		return true; // The predator is still alive
	}

	bool isPredator() override
	{
		return true; // This is a predator
	}
};

class Prey : public Fish
{
	int maxAge;
	int currentAge;

public:
	Prey() : currentAge(0), maxAge(1000) {}

	bool performAction(int& x, int& y) override
	{
		if (currentAge == maxAge)
			return false; // The prey has reached its maximum age

		currentAge++;
		return true; // The prey is still alive
	}

	bool isPredator() override
	{
		return false; // This is not a predator
	}
};

class Aquarium
{
	Fish* fishes[100][100]; // Static 2D array of fish pointers

	void populateWithPredators()
	{
		int numberOfPredators = rand() % 100; // Random number of predators
		cout << numberOfPredators << " Predators" << endl;

		for (int i = 0; i < numberOfPredators; i++)
		{
			int x = rand() % 99;
			int y = rand() % 99; // Place predator at a random position
			delete fishes[x][y]; // Remove any existing fish at that position
			fishes[x][y] = new Predator(); // Dynamically allocate a new predator
		}
	}

	bool isEmpty() // Check if the aquarium is empty
	{
		for (int i = 0; i < 100; i++)
		{
			for (int j = 0; j < 100; j++)
			{
				if (fishes[i][j] != nullptr) // Found a fish in the aquarium
					return false; // Aquarium is not empty
			}
		}
		return true; // Aquarium is empty
	}

public:
	Aquarium() // Initialize the aquarium with prey
	{
		for (int i = 0; i < 100; i++)
		{
			for (int j = 0; j < 100; j++)
			{
				fishes[i][j] = new Prey(); // Dynamically allocate prey
			}
		}
		populateWithPredators(); // Fill the aquarium with predators
	}

	void simulate() // Simulate the aquarium's ecosystem
	{
		while (!isEmpty())
		{
			int x, y;
			for (int i = 0; i < 100; i++)
			{
				for (int j = 0; j < 100; j++)
				{
					x = i; 
					y = j;
					if (fishes[i][j] != nullptr)
					{
						if (!fishes[i][j]->performAction(x, y))
						{
							cout << fishes[i][j]->isPredator();
							delete fishes[i][j]; // Remove dead fish
							fishes[i][j] = nullptr; // Mark position as empty
						}
						else
						{
							if (x >= 0 && x < 100 && y >= 0 && y < 100 && fishes[x][y] == nullptr)
							{
								fishes[x][y] = fishes[i][j]; // Move fish to new position
								fishes[i][j] = nullptr; // Mark old position as empty
							}
						}
					}
				}
			}
		}
	}

