namespace ECE141 {
  using namespace std;

  class HelpStatement : public Statement {
  public:
      HelpStatement(Keywords statementType, Keywords requestedKey) 
          : Statement(statementType), key(requestedKey) {}

      unordered_map<Keywords, std::string> helpKeywordMap = {
          {Keywords::help_kw, "\t -- help  - shows this list of commands\n"},
          {Keywords::version_kw, "\t -- version  -- shows the current version of this application\n"},
          {Keywords::quit_kw, "\t -- quit  -- terminates the execution of this DB application\n"},
          {Keywords::create_kw, "\t -- create database <name>  -- create a new database named <name>\n"},
          {Keywords::drop_kw, "\t -- drop database <name>   -- delete the database named <name>\n"},
          {Keywords::use_kw, "\t -- use database <name>   -- switch to the database named <name>\n"},
          {Keywords::describe_kw, "\t -- describe database <name>  -- show the description of the database named <name>\n"},
          {Keywords::show_kw, "\t -- show databases  -- shows the list of available databases\n"}
      };

      StatusResult run(std::ostream &outputStream) const override {
          if (key == Keywords::all_kw) {
              outputStream << "help -- the available list of commands shown below:" << std::endl;
              for (const auto& entry : helpKeywordMap) {
                  outputStream << entry.second;
              }
          } else {
              auto it = helpKeywordMap.find(key);
              if (it == helpKeywordMap.end()) {
                  outputStream << "\t Unknown Keyword" << std::endl;
              } else {
                  outputStream << it->second;
              }
          }
          return StatusResult();
      }

  protected:
      Keywords key;
  };

  class VersionStatement : public Statement {
  public:
      VersionStatement() : Statement(Keywords::version_kw) {}

      StatusResult run(std::ostream &outputStream) const override {
          outputStream << "version ECE141b-1" << std::endl;
          return StatusResult();
      }
  };

  class QuitStatement : public Statement {
  public:
      QuitStatement() : Statement(Keywords::quit_kw) {}

      StatusResult run(std::ostream &outputStream) const override {
          return StatusResult(Errors::userTerminated, 4998);
      }
  };

  AppCmdProcessor::AppCmdProcessor(CommandProcessor *nextProcessor) 
      : CommandProcessor(nextProcessor) {}

  AppCmdProcessor::~AppCmdProcessor() {}

  StatusResult AppCmdProcessor::interpret(const Statement &statement) {
      return statement.run(std::cout);
  }

  Statement* AppCmdProcessor::getStatement(Tokenizer &tokenizer) {
      Statement* currentStatement = nullptr;
      while (tokenizer.more()) {
          Token currentToken = tokenizer.current();
          Keywords keyword = currentToken.keyword;

          if (currentToken.type == TokenType::keyword) {
              tokenizer.next();
              if (keyword == Keywords::help_kw) {
                  currentStatement = tokenizer.more() ? 
                      new HelpStatement(Keywords::help_kw, tokenizer.current().keyword) : 
                      new HelpStatement(Keywords::help_kw, Keywords::all_kw);
              } else if (keyword == Keywords::version_kw) {
                  currentStatement = new VersionStatement();
              } else if (keyword == Keywords::quit_kw) {
                  currentStatement = new QuitStatement();
              }
          }
          tokenizer.next();
      }

      if (!currentStatement) {
          tokenizer.restart();
          next = new DBProcessor();
      }
      return currentStatement;
  }
}

