class Account
{
public:
    Account();
    Account(int accountNumber, int password);
    ~Account();

    void setAccountNumber(int accountNumber);
    int getAccountNumber() const;

    void setPassword(int password);
    int getPassword() const;

    void setLoginStatus(int status);
    int getLoginStatus() const;

    void login();

private:
    int accountNumber;
    int password;
    int loginStatus;
};

Account::Account() {}

Account::Account(int accountNumber, int password)
    : accountNumber(accountNumber), password(password) {}

Account::~Account() {}

void Account::setAccountNumber(int accountNumber) {
    this->accountNumber = accountNumber;
}

int Account::getAccountNumber() const {
    return this->accountNumber;
}

void Account::setPassword(int password) {
    this->password = password;
}

int Account::getPassword() const {
    return this->password;
}

void Account::setLoginStatus(int status) {
    this->loginStatus = status;
}

int Account::getLoginStatus() const {
    return this->loginStatus;
}

// Handles user login by verifying account number and password against stored data
void Account::login() {
    int inputAccountNumber;
    int inputPassword;
    int storedAccountNumber, storedPassword, totalAccounts, temp;

    cout << "Please log in to the system" << endl;
    cout << "Enter account number: ";
    cin >> inputAccountNumber;
    cout << "Enter password: ";
    cin >> inputPassword;
    cout << "Entered Account Number: " << inputAccountNumber << "\t Entered Password: " << inputPassword << endl;

    setLoginStatus(0);
    fstream accountFile;
    accountFile.open("TaiKhoan.txt", ios::in);

    if (!accountFile.is_open()) {
        cout << "Unable to open file TaiKhoan.txt" << endl;
        return;
    }

    accountFile >> totalAccounts;

    while (!accountFile.eof()) {
        for (int i = 0; i < totalAccounts; i++) {
            accountFile >> storedAccountNumber;
            if (i % 2 == 0) {
                if (storedAccountNumber == inputAccountNumber) {
                    accountFile >> storedPassword;
                    if (storedPassword == inputPassword) {
                        i++;
                        setLoginStatus(1);
                    } else {
                        i++;
                        setLoginStatus(0);
                    }
                } else {
                    i++;
                    accountFile >> temp;
                }
            }
        }
    }

    accountFile.close();
}

