using namespace std;

class BankAccount {
public:
    int accountNumber;          // Account number
    char accountHolderName[50]; // Name of account holder
    char accountType;           // Type of account (C/S)
    int balance;                // Current balance

    void createAccount();        // Create a new account
    void modifyAccount();        // Modify existing account information
    void displayAccount() const; // Display account details
    void deposit(int amount);    // Deposit money into account
    void withdraw(int amount);   // Withdraw money from account
    int getAccountNumber() const; // Get account number
    int getBalance() const;      // Get current balance
    char getAccountType() const; // Get account type
};

void BankAccount::createAccount() {
    cout << "\nEnter account number: ";
    cin >> accountNumber;
    cout << "\nEnter the name of the account holder: ";
    cin.ignore();
    cin.getline(accountHolderName, 50);
    cout << "\nEnter Type of the account (C/S): ";
    cin >> accountType;
    cout << "\nEnter the initial amount (>= 500 for saving and >=100 for current): ";
    cin >> balance;
    cout << "\n\n\nAccount Created...";
}

void BankAccount::displayAccount() const {
    cout << "\nAccount No.: " << accountNumber;
    cout << "\nAccount holder name: " << accountHolderName;
    cout << "\nType of Account: " << accountType;
    cout << "\nBalance: " << balance;
}

void BankAccount::modifyAccount() {
    cout << "\nAccount No.: " << accountNumber;
    cout << "\nModify Account Holder Name: ";
    cin.ignore();
    cin.getline(accountHolderName, 50);
    cout << "\nModify Type of Account: ";
    cin >> accountType;
    cout << "\nModify initial deposit: ";
    cin >> balance;
}

void BankAccount::deposit(int amount) {
    balance += amount;
}

void BankAccount::withdraw(int amount) {
    balance -= amount;
}

int BankAccount::getAccountNumber() const {
    return accountNumber;
}

int BankAccount::getBalance() const {
    return balance;
}

char BankAccount::getAccountType() const {
    return accountType;
}

