static uint8_t command_data[] = {0x01, 0x02, 0x03, 0x10};
static std::vector<uint8_t> initial_command(command_data, command_data + sizeof(command_data) / sizeof(uint8_t));

class Command
{
  public:
    // Constructor to initialize command vector with a specified size
    Command(size_t size)
    {
        command_vector.resize(size);
    }

    // Destructor to indicate command destruction
    ~Command()
    {
        std::cout << "Command Destroyed" << std::endl;
    }

    // Retrieve the command vector
    std::vector<uint8_t> get_command()
    {
        return command_vector;
    }

    // Get the command ID from the last element of the command vector
    int get_command_id()
    {
        return command_vector[3];
    }

    // Set the command vector with new input and return its size
    size_t set_command(std::vector<uint8_t> &input)
    {
        command_vector = input;
        return command_vector.size();
    }

  private:
    std::vector<uint8_t> command_vector;
};

// Create a unique pointer to a Command object and initialize it with initial_command
std::unique_ptr<Command> create_command()
{
    std::unique_ptr<Command> command_instance(new Command(4));

    int result = command_instance->set_command(initial_command);
    std::cout << "result = " << result << std::endl;
    return std::move(command_instance);
}

int main()
{
    std::vector<uint8_t> command_data_02(10, 0x02);
    std::unique_ptr<Command> command_instance_01 = create_command();

    // Set command with new data and display the size
    std::cout << "command_instance_01->set() = " << command_instance_01->set_command(command_data_02) << std::endl;

    command_instance_01.reset();

    // Check if the command instance is empty after reset
    if (command_instance_01 == nullptr)
        std::cout << "command_instance_01 is empty" << std::endl;
    else
        std::cout << "command_instance_01->get_command_id() = " << command_instance_01->get_command_id() << std::endl;

    std::cout << "hello world" << std::endl;
    return 0;
}

