using namespace std;

typedef pair<int, int> IndexFrequencyPair;
typedef pair<float, int> FloatIndexPair;	
typedef pair<int, float> IndexFloatPair;

class CustomSorter {    
public:    
    bool operator()(const IndexFrequencyPair& pair1, const IndexFrequencyPair& pair2) {   
        if (pair1.second == pair2.second) {
            return pair1.first < pair2.first;
        }
        return pair1.second > pair2.second;
    }
};

class Graph {
private:
    int vertexCount;  
    vector<vector<IndexFloatPair>> adjacencyList; 
    vector<vector<int>> categoryList; 
    int edgeCount; 
    vector<vector<float>> distanceMatrix;
    vector<vector<float>> nextMatrix;
    bool requiresUpdate = true; 

public:
    Graph(int vertices) {
        vertexCount = vertices;
        adjacencyList.resize(vertices + 1);
        categoryList.resize(vertices + 1);	
        scanf("%d\n", &edgeCount);

        int categoryIndex;
        for (int j = 0; j < vertexCount; j++) {
            cin >> categoryIndex;
            categoryList[categoryIndex].push_back(j + 1);
        }

        int vertex1, vertex2;
        float weight;
        for (int i = 0; i < edgeCount; i++) {
            cin >> vertex1 >> vertex2 >> weight;
            addEdge(vertex1, vertex2, weight);	
        }
    }

    void addEdge(int vertex1, int vertex2, float weight) {
        IndexFloatPair edge = make_pair(vertex2, weight);
        adjacencyList[vertex1].push_back(edge);
    } 

    void calculateMinimumTime(int source, float optimalWeight, int printFlag) {
        vector<float> distances(vertexCount + 1, pow(2, 20));
        priority_queue<FloatIndexPair, vector<FloatIndexPair>, greater<FloatIndexPair>> priorityQueue;
        priorityQueue.push(make_pair(0, source));
        distances[source] = 0;

        while (!priorityQueue.empty()) {
            int currentVertex = priorityQueue.top().second;
            priorityQueue.pop();
            for (const auto& neighbor : adjacencyList[currentVertex]) {
                int adjacentVertex = neighbor.first;
                float edgeWeight = neighbor.second;
                if (distances[adjacentVertex] > distances[currentVertex] + edgeWeight) {
                    distances[adjacentVertex] = distances[currentVertex] + edgeWeight;
                    priorityQueue.push(make_pair(distances[adjacentVertex], adjacentVertex));
                }
            }
        }

        if (printFlag == 1) {
            for (int i = 1; i <= vertexCount; i++) {
                if (distances[i] < pow(2, 20) && distances[i] != 0) {
                    printf("%0.3f ", distances[i]);    
                } else if (distances[i] == 0) {
                    cout << "0.000 ";
                } else {
                    cout << "-1.000 "; 
                }
            }
        } else {
            requiresUpdate = true;
            for (auto& neighbor : adjacencyList[source]) {
                if (neighbor.second > optimalWeight) {
                    neighbor.second = optimalWeight;
                    distances[neighbor.first] = optimalWeight;    
                }
            }
            for (int i = 1; i <= vertexCount; i++) {
                if (distances[i] > optimalWeight) {
                    addEdge(source, i, optimalWeight);
                }
            }
        }
    }

    void findTopK(int category, int k) {
        vector<IndexFrequencyPair> frequencyReference(vertexCount + 1, make_pair(0, 0));

        for (int i = 0; i < categoryList[category].size(); i++) {
            int currentVertex = categoryList[category][i];
            for (const auto& neighbor : adjacencyList[currentVertex]) {                  
                int adjacentVertex = neighbor.first;
                frequencyReference[adjacentVertex].second++;
            }
        }

        CustomSorter sorter;
        sort(frequencyReference.begin(), frequencyReference.end(), sorter);

        int size = 0;
        for (int l = 0; l < frequencyReference.size(); l++) {
            if (frequencyReference[l].second == 0) {
                size = l;
                break;
            }
        }
        k = min(k, size);
        for (int i = 0; i < k; i++) {
            cout << frequencyReference[i].first;
            if (i != k - 1) {
                cout << " ";	
            }
        }
    }

    void calculatePairwiseDistance(int category1, int category2) {
        if (requiresUpdate) {
            distanceMatrix = vector<vector<float>>(vertexCount + 1, vector<float>(vertexCount + 1, pow(2, 20)));
            nextMatrix = vector<vector<float>>(vertexCount + 1, vector<float>(vertexCount + 1, -1));
            for (int i = 1; i <= vertexCount; i++) {
                for (const auto& neighbor : adjacencyList[i]) {
                    int adjacentVertex = neighbor.first;
                    distanceMatrix[i][adjacentVertex] = neighbor.second;
                    nextMatrix[i][adjacentVertex] = adjacentVertex;
                }
            }

            for (int k = 1; k <= vertexCount; k++) {
                for (int i = 1; i <= vertexCount; i++) {
                    for (int j = 1; j <= vertexCount; j++) {
                        if (distanceMatrix[i][k] + distanceMatrix[k][j] < distanceMatrix[i][j]) {
                            distanceMatrix[i][j] = distanceMatrix[i][k] + distanceMatrix[k][j];
                            nextMatrix[i][j] = nextMatrix[i][k];
                        } else if (distanceMatrix[i][k] + distanceMatrix[k][j] == distanceMatrix[i][j]) {
                            if (nextMatrix[i][j] > nextMatrix[i][k]) {
                                nextMatrix[i][j] = nextMatrix[i][k];
                            }
                        }
                    }
                }
            }
            requiresUpdate = false;
        }        

        vector<int> path;
        for (int j1 = 0; j1 < categoryList[category1].size(); j1++) {
            for (int j2 = 0; j2 < categoryList[category2].size(); j2++) {
                int vertex1 = categoryList[category1][j1];
                int vertex2 = categoryList[category2][j2];
                if (nextMatrix[vertex1][vertex2] == -1) {
                    cout << vertex1 << " " << vertex2;
                    printf("\t");
                    cout << "-1";
                } else {                       
                    int currentVertex = vertex1;
                    cout << vertex1 << " " << vertex2 << "\t" << vertex1 << " ";
                    while (currentVertex != vertex2) {
                        currentVertex = nextMatrix[currentVertex][vertex2];
                        cout << currentVertex << " ";
                    }
                }
                cout << endl;
            }
        }
    }
};

int main() {
    int numberOfVertices;
    cin >> numberOfVertices;
    Graph graph(numberOfVertices);
    string command;
    int parameter1, parameter2;
    float parameter3;

    while (cin >> command >> parameter1) {
        if (command == "sssp") {
            graph.calculateMinimumTime(parameter1, 1, 1);
            cout << endl;
        } else if (command == "update") {
            cin >> parameter3;
            graph.calculateMinimumTime(parameter1, parameter3, 0);
        } else if (command == "top-k") {
            cin >> parameter2;
            graph.findTopK(parameter1, parameter2);
            cout << endl;
        } else if (command == "apsp") {
            cin >> parameter2;
            graph.calculatePairwiseDistance(parameter1, parameter2);
        }
    }
    return 0;
}

