struct Assoc 
{
	vector< pair <string, int> > vec;

	int y;

	//overload operator []
    int& operator[](const string& s) 
	{
		for(auto x : vec)
		{
			if( s == x.first)
		    {
				y = x.second;
				return y;   
		    }
    	}

  		vec.push_back({s, 0});

	    return vec.back().second;
	}
};


