#include <iostream>
#include <cstring>

using namespace std;

int instanceCount = 1;

class Data {
    char text[50];
    int identifier;

public:
    // Constructor initializes the text and assigns a unique identifier
    Data(char *inputText) {
        strcpy(text, inputText);
        identifier = instanceCount++;
    }

    // Displays the data along with its identifier
    void display() {
        cout << "Data " << identifier << " = " << text << endl;
    }

    // Compares the text of this object with another Data object
    void compare(Data &other);

    // Destructor releases resources and notifies of memory release
    ~Data() {
        cout << "Release Memory allocated to " << text << endl;
    }
};

// Compares the text of two Data objects and outputs the result
void Data::compare(Data &other) {
    if (strcmp(other.text, text)) {
        cout << "Both objects have different text." << endl;
    } else {
        cout << "Both objects have same text." << endl;
    }
}

int main() {
    Data data1("Obfuscation");
    Data data2("Obstruction");

    data1.display();
    data2.display();
    data1.compare(data2);

    return 0;
}

