class Student
{
private:
    string studentID, fullName;
    double mathScore, physicsScore, chemistryScore;

public:
    // Collects student information from user input
    void Input()
    {
        cin.ignore();
        cout << " - Enter student ID: ";
        getline(cin, studentID);
        cout << " - Enter full name: ";
        getline(cin, fullName);
        cout << " - Enter math score: ";
        cin >> mathScore;
        cout << " - Enter physics score: ";
        cin >> physicsScore;
        cout << " - Enter chemistry score: ";
        cin >> chemistryScore;
    }

    // Outputs student information in a formatted manner
    void Output()
    {
        cout << setw(10) << studentID;
        cout << setw(20) << fullName;
        cout << setw(10) << mathScore;
        cout << setw(10) << physicsScore;
        cout << setw(10) << chemistryScore;
        cout << setw(10) << TotalScore();
        cout << endl;
    }

    // Calculates the total score of the student
    double TotalScore() const
    {
        return mathScore + physicsScore + chemistryScore;
    }

    friend void BubbleSort(Student*, int);
};

void BubbleSort(Student* students, int count)
{
    // Sorts students based on their total scores using bubble sort algorithm
    for (int i = 1; i < count; ++i)
    {
        for (int j = count - 1; j >= i; --j)
        {
            if (students[j].TotalScore() < students[j - 1].TotalScore())
            {
                swap(students[j], students[j - 1]);
            }
        }
    }
}

int main(int argc, char const* argv[])
{
    int studentCount;
    cout << "* Enter number of students: ";
    cin >> studentCount;

    Student* students = new Student[studentCount];
    cout << "================== Enter list of " << studentCount << " students ==================" << endl;

    for (int i = 0; i < studentCount; ++i)
    {
        cout << "* Information for student " << i + 1 << ": " << endl;
        students[i].Input();
    }

    // Sort the students by total score
    BubbleSort(students, studentCount);

    cout << "========= List of " << studentCount << " students sorted by total score =========" << endl << endl;

    cout << setw(10) << "Student ID";
    cout << setw(20) << "Full Name";
    cout << setw(10) << "Math";
    cout << setw(10) << "Physics";
    cout << setw(10) << "Chemistry";
    cout << setw(10) << "Total";
    cout << endl;

    for (int i = 0; i < studentCount; ++i)
    {
        students[i].Output();
    }

    delete[] students; // Free allocated memory
    return 0;
}

