#pragma once
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

class DeleteCommand : public Useful, public Parse, public DataManipCommands
{
    char* columnName;
    string initialCommand;
    static const int minTableNameLength;
    char* value;

public:
    // Verifies if the specified table exists
    bool verifyIfExists(char* tableName) {
        bool exists = this->Useful::verifyIfExists(this->tableName);
        cout << "Searching for the table...";
        return exists;
    }

    // Deletes entries from the specified table based on the given criteria
    void deleteFrom() {
        string fileName = string(this->tableName) + ".bin";
        ifstream inputFile(fileName, ios::in | ios::binary);
        ofstream tempFile("temp.bin", ios::out | ios::binary);
        bool entryFound = false;
        int position = 0;
        string textBuffer[1000];
        int intBuffer[1000];
        float floatBuffer[1000];
        int textLengthBuffer[1000];

        if (inputFile.is_open()) {
            inputFile.seekg(0, inputFile.end);
            int fileLength = inputFile.tellg();
            inputFile.seekg(0, inputFile.beg);

            while (position < fileLength) {
                ifstream schemaFile(string(this->tableName) + ".txt", ios::in);
                if (schemaFile.is_open()) {
                    int intIndex = 0, textIndex = 0, floatIndex = 0, bufferIndex = 0;

                    while (!schemaFile.eof() && schemaFile.is_open() && position < fileLength) {
                        char buffer[1000];
                        schemaFile.getline(buffer, 1000);
                        this->currentColumn = string(buffer);
                        this->currentType = string(buffer);
                        this->currentColumn = this->currentColumn.substr(0, this->currentColumn.find_first_of(" "));
                        int typeStartIndex = this->currentType.find_first_of(" ");
                        this->currentType = this->currentType.substr(typeStartIndex + 1, this->currentType.size() - typeStartIndex);
                        this->currentType = this->currentType.substr(0, this->currentType.find_first_of(" "));

                        // Process based on data type
                        if (this->currentType == "integer") {
                            int currentInt;
                            inputFile.read(reinterpret_cast<char*>(&currentInt), sizeof(int));
                            intBuffer[intIndex++] = currentInt;
                            if (this->value == to_string(currentInt)) {
                                entryFound = true;
                            }
                            position += sizeof(currentInt);
                        } else if (this->currentType == "float") {
                            float currentFloat;
                            inputFile.read(reinterpret_cast<char*>(&currentFloat), sizeof(float));
                            floatBuffer[floatIndex++] = currentFloat;
                            if (this->value == to_string(currentFloat)) {
                                entryFound = true;
                            }
                            position += sizeof(currentFloat);
                        } else if (this->currentType == "text") {
                            int currentTextLength;
                            string text;
                            inputFile.read(reinterpret_cast<char*>(&currentTextLength), sizeof(int));
                            char textBuffer[100];
                            inputFile.read(textBuffer, currentTextLength * sizeof(char));
                            textBuffer[currentTextLength] = '\0';
                            text = string(textBuffer);
                            textLengthBuffer[bufferIndex++] = currentTextLength;
                            textBuffer[textIndex++] = text;
                            if (strcmp(this->value, textBuffer) == 0) {
                                entryFound = true;
                            }
                            position += sizeof(char) * currentTextLength + sizeof(int);
                        }
                    }
                    schemaFile.close();

                    // If no matching entry was found, copy existing entries to the temp file
                    if (!entryFound) {
                        schemaFile.open(string(this->tableName) + ".txt", ios::in);
                        if (schemaFile.is_open()) {
                            int intIndex = 0, textIndex = 0, floatIndex = 0, bufferIndex = 0;

                            while (!schemaFile.eof() && schemaFile.is_open()) {
                                char buffer[1000];
                                schemaFile.getline(buffer, 1000);
                                this->currentColumn = string(buffer);
                                this->currentType = string(buffer);
                                this->currentColumn = this->currentColumn.substr(0, this->currentColumn.find_first_of(" "));
                                int typeStartIndex = this->currentType.find_first_of(" ");
                                this->currentType = this->currentType.substr(typeStartIndex + 1, this->currentType.size() - typeStartIndex);
                                this->currentType = this->currentType.substr(0, this->currentType.find_first_of(" "));

                                // Write data to temp file based on type
                                if (this->currentType == "integer") {
                                    int currentInt = intBuffer[intIndex++];
                                    tempFile.write(reinterpret_cast<char*>(&currentInt), sizeof(int));
                                } else if (this->currentType == "float") {
                                    float currentFloat = floatBuffer[floatIndex++];
                                    tempFile.write(reinterpret_cast<char*>(&currentFloat), sizeof(float));
                                } else if (this->currentType == "text") {
                                    int currentTextLength = textLengthBuffer[bufferIndex];
                                    string text = textBuffer[textIndex++];
                                    tempFile.write(reinterpret_cast<char*>(&currentTextLength), sizeof(int));
                                    tempFile.write(text.c_str(), sizeof(char) * currentTextLength);
                                }
                            }
                            schemaFile.close();
                        }
                    }

                    // Clean up and finalize deletion
                    if (entryFound) {
                        entryFound = false;
                    }
                    columnBinary.clear();
                }

                if (position == fileLength) {
                    inputFile.close();
                    tempFile.close();
                    remove(fileName.c_str());
                    rename("temp.bin", fileName.c_str());
                }
            }
        }
    }

    DeleteCommand() : tableName(nullptr), sizeTableName(0), columnName(nullptr), value(nullptr) {}

    DeleteCommand(const char* tableName, int sizeTableName, const char* columnName, const char* value) {
        this->columnName = nullptr;
        this->tableName = nullptr;
        this->value = nullptr;
        cout << "New DELETE FROM command" << endl;

        if (tableName != nullptr) {
            this->setTableName(tableName);
            this->sizeTableName = sizeTableName;
            this->setColumnName(columnName);
            this->setValue(value);
        } else {
            cout << "Please enter valid values" << endl;
        }
    }

    void setTableName(const char* tableName) {
        if (minTableNameLength <= strlen(tableName)) {
            delete[] this->tableName;
            this->tableName = new char[strlen(tableName) + 1];
            strcpy(this->tableName, tableName);
        } else {
            cout << "You need to enter a valid table name" << endl;
        }
    }

    void setColumnName(const char* columnName) {
        if (columnName != nullptr) {
            delete[] this->columnName;
            this->columnName = new char[strlen(columnName) + 1];
            strcpy(this->columnName, columnName);
        } else {
            cout << "You need to enter a valid column name" << endl;
        }
    }

    void setValue(const char* value) {
        if (value != nullptr) {
            delete[] this->value;
            this->value = new char[strlen(value) + 1];
            strcpy(this->value, value);
        } else {
            cout << "You need to enter a valid value" << endl;
        }
    }

    void receiveCommand(string command) {
        this->initialCommand = command;
        if (this->initialCommand.find('\r') != string::npos) {
            int carriageReturnIndex = this->initialCommand.find('\r');
            this->initialCommand = this->initialCommand.substr(0, carriageReturnIndex);
        }
        createParse();
    }

    void createParse() {
        int commandSize = this->initialCommand.size();
        this->initialCommand = this->initialCommand.substr(7, commandSize - 7);

        if (initialCommand.find("FROM") == 0) {
            commandSize = this->initialCommand.size();
            this->initialCommand = this->initialCommand.substr(5, commandSize - 5);
            commandSize = this->initialCommand.size();

            this->sizeTableName = initialCommand.find_first_of("WHERE") - 1;
            if (this->sizeTableName < 0 || this->sizeTableName >= commandSize) {
                cout << endl << "You forgot the WHERE clause";
            } else {
                this->tableName = new char[this->sizeTableName + 1];
                strcpy(this->tableName, initialCommand.substr(0, this->sizeTableName).c_str());
                bool isValid = true;

                for (int i = 0; i < this->sizeTableName && isValid; i++) {
                    if ((this->tableName[i] < 'a' && this->tableName[i] != '_' && (this->tableName[i] < 48 || this->tableName[i] > 57)) || this->tableName[i] > 'z') {
                        isValid = false;
                        break;
                    }
                }

                if (!isValid) {
                    cout << "The name you entered isn't correct";
                } else {
                    this->initialCommand = this->initialCommand.substr(this->sizeTableName + 7, commandSize);
                    commandSize = this->initialCommand.size();
                    int columnNameSize = this->initialCommand.find("=") - 1;

                    if (columnNameSize > 0 && columnNameSize <= commandSize) {
                        this->columnName = new char[columnNameSize + 1];
                        strcpy(this->columnName, this->initialCommand.substr(0, columnNameSize).c_str());
                        isValid = true;

                        for (int i = 0; i < columnNameSize && isValid; i++) {
                            if ((this->columnName[i] < 'a' && this->columnName[i] != '_' && (this->columnName[i] < 48 || this->columnName[i] > 57)) || this->columnName[i] > 'z') {
                                isValid = false;
                                break;
                            }
                        }

                        if (!isValid) {
                            cout << "The column name you entered isn't correct";
                        } else {
                            this->initialCommand = this->initialCommand.substr(columnNameSize + 3, commandSize - columnNameSize - 3);
                            if (this->value != nullptr) {
                                delete[] this->value;
                            }
                            this->value = new char[this->initialCommand.size() + 1];
                            strcpy(this->value, this->initialCommand.c_str());

                            if (verifyIfExists(this->tableName)) {
                                this->deleteFrom();
                            }

                            cout << "Delete is successful";
                        }
                    } else {
                        cout << "Please reenter the command." << endl;
                    }
                }
            }
        } else {
            cout << endl << "Please enter a valid command";
        }
    }

    ~DeleteCommand() {
        delete[] this->tableName;
        delete[] this->columnName;
        delete[] this->value;
    }

    DeleteCommand(const DeleteCommand& other) {
        this->value = nullptr;
        if (other.tableName != nullptr) {
            this->setTableName(other.tableName);
        }
        if (other.columnName != nullptr) {
            this->setColumnName(other.columnName);
        }
        if (other.value != nullptr) {
            this->setValue(other.value);
        }
        this->sizeTableName = other.sizeTableName;
    }

    friend ostream& operator<<(ostream& console, DeleteCommand& dlt);
    friend void operator>>(istream& input, DeleteCommand& del1);
    friend bool operator==(DeleteCommand del1, DeleteCommand del2);
    friend bool operator>=(DeleteCommand del1, DeleteCommand del2);

    // Overloading operator "!" to check the length of the tableName
    bool operator!() {
        return strlen(this->tableName) > 12;
    }

    // Overloading operator "+=" to concatenate table names
    DeleteCommand& operator+=(DeleteCommand& other) {
        int currentLength = strlen(this->tableName);
        char* temp = new char[currentLength + 1];
        strcpy(temp, this->tableName);
        delete[] this->tableName;

        this->tableName = new char[currentLength + strlen(other.tableName) + 1];
        strcpy(this->tableName, temp);
        strcat(this->tableName, other.tableName);
        delete[] temp;

        return *this;
    }

    // Overloading cast to int
    explicit operator int() {
        return strlen(this->tableName);
    }
};

const int DeleteCommand::minTableNameLength = 2;

ostream& operator<<(ostream& console, DeleteCommand& dlt) {
    console << endl << "\n-------------------------------------";
    if (dlt.tableName != nullptr) {
        console << endl << "The name of the table you have deleted from is: " << dlt.tableName << endl;
    }
    return console;
}

void operator>>(istream& input, DeleteCommand& del1) {
    cout << "Which table would you like to delete from?" << endl;
    char buffer[1000];
    input >> buffer;
    if (strlen(buffer) > 1) {
        del1.setTableName(buffer);
    }
    cout << "What column would you like to delete from?" << endl;
    input >> buffer;
    if (strlen(buffer) > 1) {
        del1.setColumnName(buffer);
    }
    cout << "What value would you like to search for?" << endl;
    input >> buffer;
    if (strlen(buffer) > 1) {
        del1.setValue(buffer);
    }
}

// Overloading operator "==" to compare table names
bool operator==(DeleteCommand del1, DeleteCommand del2) {
    return strcmp(del1.tableName, del2.tableName) == 0;
}

// Overloading operator ">=" to compare lengths of table names
bool operator>=(DeleteCommand del1, DeleteCommand del2) {
    return strlen(del1.tableName) >= strlen(del2.tableName);
}

